sp_widget.client_script:
/**
 * PUBLIC FILES widget (public_files) - Client Script
 */
api.controller = function ($scope, $http, $timeout, $location, $filter, $templateCache, $element) {
    var c = this;

    function safeApply(fn) {
        if ($scope.$$phase || ($scope.$root && $scope.$root.$$phase)) { if (fn) fn(); }
        else $scope.$apply(fn);
    }

    /* De-duplicated event dispatcher for file selections */
    var _lastSelectedTs = 0;
    function _dispatchSelected(kind, files) {
        var now = Date.now();
        if (now - _lastSelectedTs < 250) return;
        _lastSelectedTs = now;
        safeApply(function () {
            if (kind === 'folder') c.onFolderUploadSelected(files);
            else if (kind === 'direct') c.onDirectFilesSelected(files);
            else if (kind === 'picker') c.onPickerFilesSelected(files);
        });
    }

    /* Global bridges for native DOM file inputs - immune to AngularJS debugInfoEnabled(false) */
    window.__fmPublicPickerSelected = function (input) {
        if (!input || !input.files || !input.files.length) return;
        var files = [];
        for (var i = 0; i < input.files.length; i++) files.push(input.files[i]);
        _dispatchSelected('picker', files);
    };
    window.__fmPublicDirectSelected = function (input) {
        if (!input || !input.files || !input.files.length) return;
        var files = [];
        for (var i = 0; i < input.files.length; i++) files.push(input.files[i]);
        _dispatchSelected('direct', files);
    };
    window.__fmPublicFolderSelected = function (input) {
        if (!input || !input.files || !input.files.length) return;
        var files = [];
        for (var i = 0; i < input.files.length; i++) files.push(input.files[i]);
        _dispatchSelected('folder', files);
    };

    /* Global capture-phase change listener - works even if CSP blocks inline onchange and link function is not pasted */
    function _handleGlobalFileInput(e) {
        var t = e.target;
        if (!t || !t.getAttribute) return;
        var kind = t.getAttribute('data-fm-input');
        if (!kind) return;
        var files = [];
        if (t.files && t.files.length) {
            for (var i = 0; i < t.files.length; i++) files.push(t.files[i]);
        }
        if (!files.length) return;
        _dispatchSelected(kind, files);
    }
    document.addEventListener('change', _handleGlobalFileInput, true);

    $scope.$on('$destroy', function () {
        document.removeEventListener('change', _handleGlobalFileInput, true);
        try {
            delete window.__fmPublicPickerSelected;
            delete window.__fmPublicDirectSelected;
            delete window.__fmPublicFolderSelected;
        } catch (e) { }
    });

    /* >>> CHANGE THIS to the Page ID of your existing PRIVATE file manager page <<< */
    var PRIVATE_PAGE_ID = 'home_file';

    /* ===================================================
       STATE
    =================================================== */
    c.view = 'allfiles';        // allfiles | folders | files | recycle
    c.viewMode = 'list';        // list | grid
    c.pageSize = 10;
    c.currentPages = { allFiles: 1, rootFolders: 1, childFolders: 1, folderFiles: 1 };
    c.currentFolder = '';
    c.currentFolderName = '';
    c.searchText = '';
    c.loading = false;
    c.breadcrumb = [];

    c.folderSort = 'folder_name';
    c.fileSort = 'filename';
    c.fileTypeFilter = '';

    c.showFolderModal = false;
    c.showEditFileModal = false;
    c.showRenameFileModal = false;
    c.showUploadFolderPicker = false;
    c.showAddToFolderModal = false;
    c.showNicknameModal = false;
    c.pendingItems = [];
    c.previewFile = null;

    c.addToFolderTarget = null;
    c.selectedAddFolder = '';
    c.copyBusy = false;

    c.targetUploadFolder = '';
    c.targetUploadFolderName = '';

    c.newFolderName = '';
    c.newFolderDescription = '';
    c.newFolderColor = 'orange';
    c.editFolderTarget = null;

    c.folderColors = [
        { id: 'orange', name: 'Orange', hex: '#f59e0b' },
        { id: 'blue', name: 'Blue', hex: '#3b82f6' },
        { id: 'purple', name: 'Purple', hex: '#8b5cf6' },
        { id: 'green', name: 'Green', hex: '#10b981' },
        { id: 'pink', name: 'Pink', hex: '#ec4899' }
    ];

    c.renameFileTarget = null;
    c.renameFileName = '';
    c.editFileTarget = null;
    c.editFileDescription = '';
    c.editFileNickname = '';

    c.confirmModal = { show: false, title: '', message: '', confirmLabel: 'Confirm', danger: false, icon: 'fa-check', onConfirm: angular.noop };
    c.contextMenu = { show: false, x: 0, y: 0, item: null, type: '' };

    c.uploading = false;
    c.uploadProgress = 0;
    c.uploadIndex = 0;
    c.uploadTotal = 0;
    c.uploadCurrentName = '';

    c.allSelected = false;
    c.dragOver = false;
    c.message = '';
    c.error = '';
    c.undo = null;

    /* ---- link back to the private page (keeps picker parameters) ---- */
    c.privatePageUrl = function () {
        var url = '?id=' + PRIVATE_PAGE_ID;
        if (c.pickerMode) {
            url += '&picker=true&target_table=' + encodeURIComponent(c.targetTable) +
                '&target_sys_id=' + encodeURIComponent(c.targetSysId);
        }
        return url;
    };

    c.canCreate = function () { return !!(c.data && c.data.has_public_role); };
    c.filesCount = function () { return ((c.data && c.data.files) || []).length; };
    c.setViewMode = function (m) { c.viewMode = m; };

    c.sidebarStoragePct = function () { return 0; };

    c.getFolderColor = function (folderId, file) {
        var f = _allFolders().filter(function (i) { return i.sys_id === folderId; })[0];
        return (f && f.color) ? f.color : 'orange';
    };

    /* Reusable pager */
    $templateCache.put('fm-pager.html',
        '<div class="fm-pagination" ng-if="c.page(pgKey).total">' +
        '<span>Showing {{c.page(pgKey).start}}–{{c.page(pgKey).end}} of {{c.page(pgKey).total}}</span>' +
        '<div class="fm-pagination-controls">' +
        '<select ng-model="c.pageSize" ng-options="n for n in [10, 20, 50]" aria-label="Rows per page"></select>' +
        '<button type="button" title="First page" ng-click="c.goToPage(pgKey, 1)" ng-disabled="c.page(pgKey).page <= 1">&laquo;</button>' +
        '<button type="button" ng-click="c.previousPage(pgKey)" ng-disabled="c.page(pgKey).page <= 1">Previous</button>' +
        '<button type="button" class="fm-page-num" ng-repeat="n in c.pageNumbers(pgKey) track by $index" ' +
        'ng-class="{\'fm-page-active\': n === c.page(pgKey).page}" ng-disabled="n === \'…\'" ng-click="c.goToPage(pgKey, n)">{{n}}</button>' +
        '<button type="button" ng-click="c.nextPage(pgKey)" ng-disabled="c.page(pgKey).page >= c.page(pgKey).pages">Next</button>' +
        '<button type="button" title="Last page" ng-click="c.goToPage(pgKey, c.page(pgKey).pages)" ng-disabled="c.page(pgKey).page >= c.page(pgKey).pages">&raquo;</button>' +
        '</div></div>');

    /* ===================================================
       PICKER MODE
    =================================================== */
    var _qs = $location.search();
    c.pickerMode = _qs.picker === 'true';
    c.targetTable = _qs.target_table || '';
    c.targetSysId = _qs.target_sys_id || '';
    c.pickBusy = false;

    c.getSelectedFiles = function () {
        return ((c.data && c.data.files) || []).filter(function (f) { return f._selected; });
    };

    c.attachFiles = function (ids) {
        if (c.pickBusy || !ids || !ids.length) return;
        if (!c.targetTable || !c.targetSysId) {
            c.error = 'Missing target record. Open this page from the attachment dialog.';
            return;
        }
        c.pickBusy = true;
        _clearAlerts();

        c.server.get({
            action: 'attach_to_record', file_ids: ids,
            target_table: c.targetTable, target_sys_id: c.targetSysId
        }).then(function (res) {
            c.pickBusy = false;
            var r = (res && res.data) ? res.data : res;
            if (r && r.attached_count > 0) {
                var msg = { type: 'FM_FILE_ATTACHED', count: r.attached_count };
                try { var ch = new BroadcastChannel('fm_attach_channel'); ch.postMessage(msg); ch.close(); } catch (e) { }
                try { if (window.opener) window.opener.postMessage(msg, window.location.origin); } catch (e) { }
                if (r.error) c.error = r.error; else window.close();
            } else {
                c.error = (r && r.error) || 'Could not attach the selected file(s).';
            }
        }, function () {
            c.pickBusy = false;
            c.error = 'Server request failed. Please try again.';
        });
    };

    c.attachSelected = function () {
        c.attachFiles(c.getSelectedFiles().map(function (f) { return f.sys_id; }));
    };

    c.onRowDblClick = function (file) {
        if (!file || !file.sys_id) return;
        if (c.pickerMode) { c.attachFiles([file.sys_id]); return; }
        if (c.isImage(file)) c.preview(file);
    };

    c.rowClick = function (file, $event) {
        c.closeContextMenu();
        if (!c.pickerMode || !file) return;
        var t = $event && $event.target;
        if (t && /^(INPUT|BUTTON|A)$/i.test(t.tagName)) return;
        file._selected = !file._selected;
        c.onFileSelect();
    };

    /* ===================================================
       NAVIGATION
    =================================================== */
    function _resetNav(view) {
        c.view = view;
        c.currentFolder = '';
        c.currentFolderName = '';
        c.searchText = '';
        c.breadcrumb = [];
        _clearAlerts();
        _clearSelection();
        c.closeContextMenu();
    }

    c.setView = function (view) { _resetNav(view); c.resetPagination(); };
    c.goHome = function () { c.setView('allfiles'); };

    function _allFolders() { return (c.data && c.data.folders) || []; }
    function _allFiles() { return (c.data && c.data.files) || []; }

    function _buildCrumbs(folder) {
        var map = {};
        _allFolders().forEach(function (f) { map[f.sys_id] = f; });
        var chain = [], cur = folder, guard = 0;
        while (cur && guard++ < 25) {
            chain.unshift({ id: cur.sys_id, name: cur.folder_name });
            cur = cur.parent_folder ? map[cur.parent_folder] : null;
        }
        return [{ id: '', name: 'Folders', view: 'folders' }].concat(chain);
    }

    c.openFolder = function (folder, rebuild) {
        if (!folder) return;
        if (c.view === 'files' && !rebuild && c.breadcrumb.length) c.breadcrumb.push({ id: folder.sys_id, name: folder.folder_name });
        else c.breadcrumb = _buildCrumbs(folder);

        c.currentFolder = folder.sys_id;
        c.currentFolderName = folder.folder_name;
        c.view = 'files';
        c.searchText = '';
        c.resetPagination();
        _clearAlerts();
        _clearSelection();
        c.closeContextMenu();
    };

    c.openFolderById = function (folderId) {
        var folder = _allFolders().filter(function (f) { return f.sys_id === folderId; })[0];
        if (folder) c.openFolder(folder, true);
    };

    c.navigateBreadcrumb = function (index) {
        var crumb = c.breadcrumb[index];
        if (!crumb) return;
        if (!crumb.id) { c.setView(crumb.view || 'folders'); return; }
        c.breadcrumb = c.breadcrumb.slice(0, index + 1);
        c.currentFolder = crumb.id;
        c.currentFolderName = crumb.name;
        c.view = 'files';
        c.searchText = '';
        c.resetPagination();
        _clearSelection();
        c.closeContextMenu();
    };

    c.navigateBack = function () {
        if (c.breadcrumb.length > 2) c.navigateBreadcrumb(c.breadcrumb.length - 2);
        else c.navigateBreadcrumb(0);
    };
    c.backLabel = function () {
        if (c.breadcrumb.length > 2) return 'Back';
        return 'Back to Folders';
    };

    /* ===================================================
       QUERIES
    =================================================== */
    c.rootFolders = function () { return _allFolders().filter(function (f) { return !f.parent_folder; }); };
    c.recycleCount = function () {
        return (((c.data && c.data.recycleFiles) || []).length) + (((c.data && c.data.recycleFolders) || []).length);
    };
    c.editableFolders = function () { return c.canCreate() ? _allFolders() : []; };
    c.myFolders = function () { return (c.data && c.data.myFolders) || []; };

    c.foldersInCurrentFolder = function () {
        return _allFolders().filter(function (f) { return (f.parent_folder || '') === (c.currentFolder || ''); });
    };
    c.filesInCurrentFolder = function () {
        return _allFiles().filter(function (f) { return (f.folder || '') === (c.currentFolder || ''); });
    };
    c.currentFolderCanEdit = function () {
        var m = _allFolders().filter(function (f) { return f.sys_id === c.currentFolder; })[0];
        return !!(m && m.can_edit);
    };
    c.getFolderName = function (folderId, file) {
        if (file && file.folder_name) return file.folder_name;
        var f = _allFolders().filter(function (i) { return i.sys_id === folderId; })[0];
        return f ? f.folder_name : '';
    };

    c.allFilesFiltered = function () {
        return _allFiles().filter(function (file) {
            if (!c.matchFile(file)) return false;
            if (!c.fileTypeFilter) return true;
            var ext = (file.file_extension || '').toLowerCase();
            switch (c.fileTypeFilter) {
                case 'image': return ['png', 'jpg', 'jpeg', 'gif', 'webp', 'bmp', 'svg'].indexOf(ext) !== -1;
                case 'document': return ['doc', 'docx', 'odt', 'rtf', 'txt', 'md', 'xls', 'xlsx', 'csv', 'ppt', 'pptx'].indexOf(ext) !== -1;
                case 'pdf': return ext === 'pdf';
                case 'archive': return ['zip', 'rar', '7z', 'tar', 'gz'].indexOf(ext) !== -1;
                default: return true;
            }
        });
    };
    c.searchFiles = function (f) { return c.matchFile(f); };
    c.searchFolders = function (f) { return !c.searchText || (f.folder_name || '').toLowerCase().indexOf(c.searchText.toLowerCase()) !== -1; };

    var _cc = { ref: null, f: {}, d: {} };
    function _buildCounts() {
        if (_cc.ref === c.data) return;
        _cc = { ref: c.data, f: {}, d: {} };
        _allFiles().forEach(function (x) { if (x.folder) _cc.f[x.folder] = (_cc.f[x.folder] || 0) + 1; });
        _allFolders().forEach(function (x) { if (x.parent_folder) _cc.d[x.parent_folder] = (_cc.d[x.parent_folder] || 0) + 1; });
    }
    c.countLabel = function (n, word) { return n + ' ' + word + (n === 1 ? '' : 's'); };
    c.folderCounts = function (folder) {
        _buildCounts();
        return { files: _cc.f[folder.sys_id] || 0, folders: _cc.d[folder.sys_id] || 0 };
    };

    c.findItem = function (type, id) {
        var d = c.data || {};
        var lists = { file: d.files, folder: d.folders, recycle_file: d.recycleFiles, recycle_folder: d.recycleFolders };
        return (lists[type] || []).filter(function (x) { return x.sys_id === id; })[0] || null;
    };

    /* ===================================================
       LISTS + PAGINATION
    =================================================== */
    function _sortFiles(l) { return $filter('orderBy')(l, c.fileSort); }
    function _sortFolders(l) { return $filter('orderBy')(l, c.folderSort); }

    var _lists = {
        allFiles: function () { return _sortFiles(c.allFilesFiltered()); },
        rootFolders: function () { return _sortFolders(c.rootFolders().filter(c.searchFolders)); },
        childFolders: function () { return _sortFolders(c.foldersInCurrentFolder().filter(c.searchFolders)); },
        folderFiles: function () { return _sortFiles(c.filesInCurrentFolder().filter(c.searchFiles)); }
    };

    c.page = function (key) {
        var fn = _lists[key];
        var list = fn ? fn() : [];
        var pages = Math.max(1, Math.ceil(list.length / c.pageSize));
        var page = Math.min(Math.max(c.currentPages[key] || 1, 1), pages);
        var start = (page - 1) * c.pageSize;
        return {
            items: list.slice(start, start + c.pageSize),
            page: page, pages: pages, total: list.length,
            start: list.length ? start + 1 : 0,
            end: Math.min(page * c.pageSize, list.length)
        };
    };
    c.goToPage = function (key, n) {
        if (typeof n !== 'number') return;
        c.currentPages[key] = Math.min(Math.max(1, n), c.page(key).pages);
    };
    c.pageNumbers = function (key) {
        var p = c.page(key), out = [], i;
        if (p.pages <= 7) { for (i = 1; i <= p.pages; i++) out.push(i); return out; }
        out.push(1);
        var from = Math.max(2, p.page - 1), to = Math.min(p.pages - 1, p.page + 1);
        if (from > 2) out.push('…');
        for (i = from; i <= to; i++) out.push(i);
        if (to < p.pages - 1) out.push('…');
        out.push(p.pages);
        return out;
    };
    c.previousPage = function (key) { c.currentPages[key] = Math.max(1, c.page(key).page - 1); };
    c.nextPage = function (key) { var p = c.page(key); c.currentPages[key] = Math.min(p.pages, p.page + 1); };
    c.resetPagination = function () { Object.keys(c.currentPages).forEach(function (k) { c.currentPages[k] = 1; }); };

    $scope.$watch(function () {
        return c.searchText + '|' + c.fileTypeFilter + '|' + c.pageSize + '|' + c.fileSort + '|' + c.folderSort;
    }, function (n, o) { if (n !== o) c.resetPagination(); });

    c.toggleSort = function (field) {
        if (c.fileSort === field) c.fileSort = '-' + field;
        else c.fileSort = field;
    };
    c.getSortIcon = function (field) {
        if (c.fileSort === field) return 'fa-sort-asc';
        if (c.fileSort === '-' + field) return 'fa-sort-desc';
        return 'fa-sort';
    };

    /* ===================================================
       SERVER ACTIONS
    =================================================== */
    c.runAction = function (action, values) {
        values = values || {};
        values.action = action;
        _clearAlerts();
        return c.server.get(values).then(function (res) {
            var r = (res && res.data) ? res.data : res;
            if (r) {
                if (r.loaded) c.data = r;
                if (r.error) c.error = r.error;
                else if (r.success && !values.skip_load) c.message = r.success;
            }
            return r || {};
        }, function () {
            c.error = 'Server request failed. Please try again.';
            return { error: c.error };
        });
    };

    c.refresh = function (keepAlerts) {
        c.loading = true;
        if (keepAlerts !== true) _clearAlerts();
        return c.server.get({ action: 'refresh' }).then(function (res) {
            c.loading = false;
            var r = (res && res.data) ? res.data : res;
            if (r && r.loaded) c.data = r;
            return c.data;
        }, function () {
            c.loading = false;
            c.error = 'Unable to refresh. Please try again.';
            return c.data;
        });
    };

    var _msgTimer;
    $scope.$watch(function () { return c.message; }, function (v) {
        if (_msgTimer) $timeout.cancel(_msgTimer);
        if (v) _msgTimer = $timeout(function () { c.message = ''; c.undo = null; }, c.undo ? 8000 : 4000);
    });
    c.setUndo = function (fn) { c.undo = { fn: fn }; };
    c.runUndo = function () { var fn = c.undo && c.undo.fn; c.undo = null; if (fn) fn(); };

    /* ===================================================
       UPLOAD
    =================================================== */
    c.openUploadFolderPicker = function () {
        var available = c.editableFolders();
        if (c.currentFolder && c.currentFolderCanEdit()) {
            c.targetUploadFolder = c.currentFolder;
            c.targetUploadFolderName = c.currentFolderName;
        } else if (available.length) {
            c.targetUploadFolder = available[0].sys_id;
            c.targetUploadFolderName = available[0].folder_name;
        } else {
            c.targetUploadFolder = '';
            c.targetUploadFolderName = '';
        }
        c.showUploadFolderPicker = true;
    };

    c.triggerPickerUpload = function () {
        var el = document.getElementById('fmPickerUploadPub');
        if (el) {
            try { el.value = ''; } catch (e) { }
            el.click();
        }
    };
    c.triggerDirectUpload = function () {
        var el = document.getElementById('fmDirectUploadPub');
        if (el) {
            try { el.value = ''; } catch (e) { }
            el.click();
        }
    };

    c.onPickerFilesSelected = function (files) {
        safeApply(function () {
            files = Array.prototype.slice.call(files || []);
            if (!files.length) return;
            var folderId = c.targetUploadFolder || '';
            c.showUploadFolderPicker = false;
            _uploadFilesToFolder(files, folderId);
        });
    };
    c.onDirectFilesSelected = function (files) {
        safeApply(function () {
            files = Array.prototype.slice.call(files || []);
            if (files.length) _uploadFilesToFolder(files, c.currentFolder || '');
        });
    };
    c.uploadToFolder = function (files, folderId) {
        safeApply(function () {
            files = Array.prototype.slice.call(files || []);
            if (files.length) _uploadFilesToFolder(files, folderId || '');
        });
    };

    /* ---- XML uploads: ask for an optional nickname before uploading ---- */
    function _isXml(file) { return /\.xml$/i.test((file && file.name) || ''); }

    c.stageUpload = function (items) {
        if (!items || !items.length) return;
        if (c.uploading) { c.error = 'An upload is already in progress. Please wait.'; return; }
        var hasXml = items.some(function (it) { return _isXml(it.file); });
        if (!hasXml) { _uploadItems(items); return; }
        items.forEach(function (it) { it.isXml = _isXml(it.file); it.nickname = ''; });
        c.pendingItems = items;
        c.showNicknameModal = true;
        _clearAlerts();
    };
    c.pendingOtherCount = function () {
        return (c.pendingItems || []).filter(function (it) { return !it.isXml; }).length;
    };
    c.confirmNicknameUpload = function () {
        var items = c.pendingItems || [];
        c.pendingItems = [];
        c.showNicknameModal = false;
        items.forEach(function (it) {
            it.nickname = it.isXml ? String(it.nickname || '').replace(/[\[\]]/g, '').trim().substring(0, 50) : '';
        });
        _uploadItems(items);
    };
    c.cancelNicknameUpload = function () { c.pendingItems = []; c.showNicknameModal = false; };

    /* search matches file name OR nickname */
    c.matchFile = function (file) {
        var q = (c.searchText || '').toLowerCase();
        if (!q) return true;
        return (file.filename || '').toLowerCase().indexOf(q) !== -1 ||
            (file.nickname || '').toLowerCase().indexOf(q) !== -1;
    };

    function _uploadFilesToFolder(fileList, folderId) {
        var files = Array.prototype.slice.call(fileList || []);
        if (!files.length) return;
        c.stageUpload(files.map(function (f) { return { file: f, folderId: folderId || c.currentFolder || '' }; }));
    }

    function _getToken(res) {
        if (res && res.g_ck) return res.g_ck;
        if (c.data && c.data.g_ck) return c.data.g_ck;
        if (typeof g_ck !== 'undefined' && g_ck) return g_ck;
        if (window && window.g_ck) return window.g_ck;
        try { if (window.top && window.top.g_ck) return window.top.g_ck; } catch (e) { }
        return '';
    }

    function _uploadAttachment(file, fileSysId, cb, res) {
        var token = _getToken(res);
        var finished = false;

        function done(err) {
            if (finished) return;
            finished = true;
            $scope.$evalAsync(function () { cb(err || null); });
        }

        // 1. Try REST binary stream upload (/api/now/attachment/file)
        var streamUrl = '/api/now/attachment/file?table_name=x_1830514_fm_file' +
            '&table_sys_id=' + encodeURIComponent(fileSysId) +
            '&file_name=' + encodeURIComponent(file.name);

        var xhrStream = new XMLHttpRequest();
        var streamHandled = false;
        function streamFailed() {
            if (streamHandled) return;
            streamHandled = true;
            _tryUploadFormData();
        }

        xhrStream.open('POST', streamUrl, true);
        if (token) xhrStream.setRequestHeader('X-UserToken', token);
        xhrStream.setRequestHeader('Accept', 'application/json');
        xhrStream.setRequestHeader('Content-Type', file.type || 'application/octet-stream');

        xhrStream.onload = function () {
            if (xhrStream.status >= 200 && xhrStream.status < 300) {
                streamHandled = true;
                done(null);
            } else {
                streamFailed();
            }
        };
        xhrStream.onerror = function () { streamFailed(); };

        try {
            xhrStream.send(file);
        } catch (e) {
            streamFailed();
        }

        // 2. Try REST multipart FormData upload (/api/now/attachment/upload)
        function _tryUploadFormData() {
            if (typeof FormData === 'undefined') {
                _trySysAttachment();
                return;
            }
            var handled = false;
            function formFailed() {
                if (handled) return;
                handled = true;
                _trySysAttachment();
            }
            try {
                var xhrFd = new XMLHttpRequest();
                var fd = new FormData();
                fd.append('table_name', 'x_1830514_fm_file');
                fd.append('table_sys_id', fileSysId);
                fd.append('uploadFile', file, file.name);

                xhrFd.open('POST', '/api/now/attachment/upload', true);
                if (token) xhrFd.setRequestHeader('X-UserToken', token);
                xhrFd.setRequestHeader('Accept', 'application/json');

                xhrFd.onload = function () {
                    if (xhrFd.status >= 200 && xhrFd.status < 300) {
                        handled = true;
                        done(null);
                    } else {
                        formFailed();
                    }
                };
                xhrFd.onerror = function () { formFailed(); };
                xhrFd.send(fd);
            } catch (ex) {
                formFailed();
            }
        }

        // 3. Fallback to classic ServiceNow attachment handler (/sys_attachment.do)
        function _trySysAttachment() {
            if (typeof FormData === 'undefined') {
                done('Browser does not support FormData attachment upload.');
                return;
            }
            try {
                var xhrSys = new XMLHttpRequest();
                var fdSys = new FormData();
                fdSys.append('sysparm_table', 'x_1830514_fm_file');
                fdSys.append('sysparm_sys_id', fileSysId);
                fdSys.append('sysparm_action', 'save');
                if (token) fdSys.append('sysparm_ck', token);
                fdSys.append('attachFile', file, file.name);

                xhrSys.open('POST', '/sys_attachment.do', true);
                if (token) xhrSys.setRequestHeader('X-UserToken', token);

                xhrSys.onload = function () {
                    if (xhrSys.status >= 200 && xhrSys.status < 400) {
                        done(null);
                    } else {
                        done('Attachment upload failed with status ' + xhrSys.status);
                    }
                };
                xhrSys.onerror = function () { done('Network error while uploading attachment.'); };
                xhrSys.send(fdSys);
            } catch (ex) {
                done('Attachment upload failed.');
            }
        }
    }

    function _uploadItems(items) {
        if (!items.length) return;
        if (c.uploading) { c.error = 'An upload is already in progress. Please wait.'; return; }

        var total = items.length, index = 0, failed = [], lastError = '';
        c.uploading = true;
        c.uploadProgress = 0; c.uploadIndex = 0; c.uploadTotal = total; c.uploadCurrentName = '';
        _clearAlerts();

        function finish() {
            c.uploading = false;
            c.refresh(true).then(function () {
                if (failed.length) {
                    c.error = (lastError ? lastError + ' ' : '') + 'Failed to upload: ' + failed.join(', ');
                } else {
                    c.message = total === 1 ? '"' + items[0].file.name + '" uploaded successfully.' : total + ' files uploaded successfully.';
                }
            });
        }

        function next() {
            if (index >= total) { finish(); return; }
            var item = items[index++], file = item.file;
            var ext = file.name.indexOf('.') !== -1 ? file.name.split('.').pop().toLowerCase() : '';

            c.uploadIndex = index;
            c.uploadCurrentName = file.name;
            c.uploadProgress = Math.round(((index - 1) / total) * 100);

            // 1. Create file record with metadata (GET query string is small and clean)
            c.runAction('create_file', {
                filename: file.name,
                extension: ext,
                content_type: file.type || 'application/octet-stream',
                file_size: file.size,
                folder: item.folderId || '',
                nickname: item.nickname || '',
                skip_load: '1'
            }).then(function (result) {
                if (result.error || !result.file_sys_id) {
                    lastError = result.error || 'Failed to create file record.';
                    failed.push(file.name);
                    next();
                    return;
                }

                // 2. Upload the file binary directly using ServiceNow attachment endpoints
                _uploadAttachment(file, result.file_sys_id, function (err) {
                    if (err) {
                        lastError = err;
                        failed.push(file.name);
                        next();
                    } else {
                        c.uploadProgress = Math.round((index / total) * 100);
                        // 3. Immediately sync and copy attachment to x_1830514_fm_public_items
                        c.runAction('sync_public_attachment', {
                            file_sys_id: result.file_sys_id,
                            public_item_sys_id: result.public_item_sys_id || '',
                            skip_load: '1'
                        }).then(function () {
                            next();
                        }, function () {
                            next();
                        });
                    }
                }, result);
            }, function () {
                lastError = 'Server communication error while creating file record.';
                failed.push(file.name);
                next();
            });
        }
        next();
    }

    c.triggerFolderUpload = function () {
        var input = document.getElementById('fmFolderUpload');
        if (input) { input.value = ''; input.click(); }
        else c.error = 'Folder upload input was not found.';
    };

    c.onFolderUploadSelected = function (files) {
        safeApply(function () {
            files = Array.prototype.slice.call(files || []);
            if (!files.length) return;
            if (!c.currentFolder) { c.error = 'Open a public folder first, then upload a folder into it.'; return; }
            if (!c.currentFolderCanEdit()) { c.error = 'You do not have permission to upload into this folder.'; return; }
            _uploadFolderTree(files, c.currentFolder);
        });
    };

    function _uploadFolderTree(files, baseParent) {
        if (c.uploading) { c.error = 'An upload is already in progress. Please wait.'; return; }
        var dirs = {};
        files.forEach(function (f) {
            var parts = (f.webkitRelativePath || f.name).split('/');
            parts.pop();
            var acc = '';
            parts.forEach(function (p) { acc = acc ? acc + '/' + p : p; dirs[acc] = true; });
        });
        var paths = Object.keys(dirs).sort(function (a, b) {
            var d = a.split('/').length - b.split('/').length;
            return d !== 0 ? d : (a < b ? -1 : 1);
        });
        if (!paths.length) { c.error = 'Unable to identify the selected folder.'; return; }

        var idMap = {}, i = 0;
        c.uploading = true; c.uploadTotal = files.length; c.uploadIndex = 0; c.uploadProgress = 0;
        c.uploadCurrentName = 'Creating folders...';
        _clearAlerts();

        function nextDir() {
            if (i >= paths.length) {
                c.uploading = false;
                var items = files.map(function (f) {
                    var parts = (f.webkitRelativePath || f.name).split('/');
                    parts.pop();
                    return { file: f, folderId: idMap[parts.join('/')] };
                }).filter(function (it) { return !!it.folderId; });
                c.stageUpload(items);
                return;
            }
            var path = paths[i++], parts = path.split('/'), name = parts.pop();
            var parent = parts.length ? idMap[parts.join('/')] : baseParent;
            c.runAction('create_folder', {
                folder_name: name, description: 'Uploaded folder',
                parent_folder: parent || '', reuse_existing: '1', skip_load: '1'
            }).then(function (r) {
                if (r.error || !r.folder_sys_id) {
                    c.uploading = false;
                    c.error = r.error || ('Unable to create folder "' + name + '".');
                    return;
                }
                idMap[path] = r.folder_sys_id;
                nextDir();
            });
        }
        nextDir();
    }

