    c.openFolderModal = function () {
        c.newFolderName = ''; c.newFolderDescription = ''; c.newFolderColor = 'orange';
        c.editFolderTarget = null;
        _clearAlerts();
        c.showFolderModal = true;
        $timeout(function () { var el = document.getElementById('fmFolderNameInput'); if (el) el.focus(); }, 60);
    };
    c.openRenameFolder = function (folder) {
        c.newFolderName = folder.folder_name;
        c.newFolderDescription = '';
        c.newFolderColor = folder.color || 'orange';
        c.editFolderTarget = folder;
        _clearAlerts();
        c.showFolderModal = true;
        $timeout(function () { var el = document.getElementById('fmFolderNameInput'); if (el) { el.focus(); el.select(); } }, 60);
    };
    c.closeFolderModal = function () {
        c.showFolderModal = false; c.editFolderTarget = null;
        c.newFolderName = ''; c.newFolderDescription = ''; c.newFolderColor = 'orange';
    };
    c.onFolderNameKey = function ($event) {
        if ($event.keyCode === 13) { if (c.editFolderTarget) c.renameFolder(); else c.createFolder(); }
    };

    c.createFolder = function () {
        var name = (c.newFolderName || '').trim();
        if (!name) { c.error = 'Please enter a folder name.'; return; }
        c.runAction('create_folder', {
            folder_name: name, description: c.newFolderDescription || '',
            parent_folder: c.currentFolder || '', color: c.newFolderColor || 'orange'
        }).then(function (r) { if (!r.error) c.closeFolderModal(); });
    };

    c.renameFolder = function () {
        var name = (c.newFolderName || '').trim();
        if (!name) { c.error = 'Please enter a folder name.'; return; }
        var target = c.editFolderTarget;
        c.runAction('rename_folder', { sys_id: target.sys_id, folder_name: name, color: c.newFolderColor || 'orange' })
            .then(function (r) {
                if (r.error) return;
                if (c.currentFolder === target.sys_id) c.currentFolderName = name;
                c.breadcrumb.forEach(function (b) { if (b.id === target.sys_id) b.name = name; });
                c.closeFolderModal();
            });
    };

    /* ===================================================
       RENAME FILE / EDIT DESCRIPTION
    =================================================== */
    c.openRenameFile = function (file) {
        c.renameFileTarget = file; c.renameFileName = file.filename;
        _clearAlerts(); c.showRenameFileModal = true;
    };
    c.saveRenameFile = function () {
        var name = (c.renameFileName || '').trim();
        if (!name) { c.error = 'Please enter a file name.'; return; }
        c.runAction('rename_file', { sys_id: c.renameFileTarget.sys_id, filename: name }).then(function (r) {
            if (!r.error) { c.showRenameFileModal = false; c.renameFileTarget = null; }
        });
    };
    c.openEditFile = function (file) {
        c.editFileTarget = file; c.editFileDescription = file.description || '';
        c.editFileNickname = file.nickname || '';
        _clearAlerts(); c.showEditFileModal = true;
    };
    c.saveEditFile = function () {
        if (!c.editFileTarget) return;
        c.runAction('update_file', { sys_id: c.editFileTarget.sys_id, description: c.editFileDescription || '', nickname: c.editFileNickname || '' })
