    /* ===================================================
       CONFIRM + DELETE
    =================================================== */
    function _confirm(opts) {
        c.confirmModal = {
            show: true, title: opts.title || 'Are you sure?', message: opts.message || '',
            confirmLabel: opts.confirmLabel || 'Confirm', danger: opts.danger !== false,
            icon: opts.icon || 'fa-check', onConfirm: opts.onConfirm || angular.noop
        };
    }
    c.runConfirm = function () { var fn = c.confirmModal.onConfirm; c.confirmModal.show = false; fn(); };

    c.confirmDeleteFile = function (file) {
        _confirm({
            title: 'Move to Recycle Bin', message: 'Move "' + file.filename + '" to the Recycle Bin?',
            confirmLabel: 'Move to Bin', icon: 'fa-trash', onConfirm: function () { c.deleteFile(file); }
        });
    };
    c.confirmDeleteFolder = function (folder) {
        _confirm({
            title: 'Move Folder to Recycle Bin',
            message: 'Move folder "' + folder.folder_name + '" to the Recycle Bin? All subfolders and files inside must be removed or moved first.',
            confirmLabel: 'Move to Bin', icon: 'fa-trash', onConfirm: function () { c.deleteFolder(folder); }
        });
    };
    c.confirmPermanentDeleteFile = function (file) {
        _confirm({
            title: 'Delete File Permanently', message: 'Permanently delete "' + file.filename + '"? This action CANNOT be undone.',
            confirmLabel: 'Delete Permanently', icon: 'fa-times', onConfirm: function () { c.deleteFilePermanent(file); }
        });
    };
    c.confirmPermanentDeleteFolder = function (folder) {
        _confirm({
            title: 'Delete Folder Permanently', message: 'Permanently delete folder "' + folder.folder_name + '"? This action CANNOT be undone.',
            confirmLabel: 'Delete Permanently', icon: 'fa-times', onConfirm: function () { c.deleteFolderPermanent(folder); }
        });
    };
    c.confirmEmptyBin = function () {
        _confirm({
            title: 'Empty Recycle Bin', message: 'Permanently delete all your deleted public files and folders? This action CANNOT be undone.',
            confirmLabel: 'Empty Bin', icon: 'fa-trash', onConfirm: function () { c.emptyBin(); }
        });
    };

    c.canDeleteSelected = function () {
        return c.canCreate() && c.getSelectedFiles().some(function (f) { return f.permission === 'Owner'; });
    };
    c.confirmDeleteSelected = function () {
        var owned = c.getSelectedFiles().filter(function (f) { return f.permission === 'Owner'; });
        if (!owned.length) return;
        _confirm({
            title: 'Delete Selected Files',
            message: 'Move ' + owned.length + ' selected file(s) to the Recycle Bin? (Only files you own are deleted.)',
            confirmLabel: 'Move to Bin', icon: 'fa-trash', onConfirm: function () { _deleteBatch(owned); }
        });
    };

    function _deleteBatch(files) {
        var idx = 0, done = 0, errors = [], doneIds = [];
        _clearAlerts();
        function next() {
            if (idx >= files.length) {
                c.refresh(true).then(function () {
                    if (errors.length) c.error = 'Could not delete: ' + errors.join(', ');
                    else { c.message = done + ' file(s) moved to the Recycle Bin.'; c.setUndo(function () { _restoreBatch(doneIds); }); }
                });
                return;
            }
            var f = files[idx++];
            c.runAction('delete_file', { sys_id: f.sys_id, skip_load: '1' }).then(function (r) {
                if (r.error) errors.push(f.filename); else { done++; doneIds.push(f.sys_id); }
                next();
            });
        }
        next();
    }
    function _restoreBatch(ids) {
        var i = 0, ok = 0;
        function next() {
            if (i >= ids.length) { c.refresh(true).then(function () { c.message = ok + ' file(s) restored.'; }); return; }
            c.runAction('restore_file', { sys_id: ids[i++], skip_load: '1' }).then(function (r) { if (!r.error) ok++; next(); });
        }
        next();
    }

    c.deleteFile = function (file) {
        return c.runAction('delete_file', { sys_id: file.sys_id }).then(function (r) {
            if (!r.error) c.setUndo(function () { c.restoreFile({ sys_id: file.sys_id }); });
            return r;
        });
    };
    c.deleteFolder = function (folder) {
        return c.runAction('delete_folder', { sys_id: folder.sys_id }).then(function (r) {
            if (!r.error) c.setUndo(function () { c.restoreFolder({ sys_id: folder.sys_id }); });
            return r;
        });
    };
    c.restoreFile = function (f) { return c.runAction('restore_file', { sys_id: f.sys_id }); };
    c.restoreFolder = function (f) { return c.runAction('restore_folder', { sys_id: f.sys_id }); };
    c.deleteFilePermanent = function (f) { return c.runAction('delete_file_permanent', { sys_id: f.sys_id }); };
    c.deleteFolderPermanent = function (f) { return c.runAction('delete_folder_permanent', { sys_id: f.sys_id }); };
    c.emptyBin = function () { return c.runAction('empty_bin'); };

    /* ===================================================
       DOWNLOAD & PREVIEW
    =================================================== */
    c.downloadFile = function (file) {
        if (!file || !file.attachment_id) { c.error = 'Attachment not found.'; return; }
        window.open('/sys_attachment.do?sys_id=' + encodeURIComponent(file.attachment_id), '_blank');
    };
    c.downloadSelected = function () {
        c.getSelectedFiles().forEach(function (f, i) { $timeout(function () { c.downloadFile(f); }, i * 350); });
    };
    c.isImage = function (file) {
        if (!file) return false;
        var ext = (file.file_extension || '').toLowerCase(), type = (file.content_type || '').toLowerCase();
        return type.indexOf('image/') === 0 || ['png', 'jpg', 'jpeg', 'gif', 'webp', 'bmp', 'svg'].indexOf(ext) !== -1;
    };
    c.preview = function (file) {
        if (!file || !file.attachment_id) { c.error = 'Attachment not found.'; return; }
        c.previewFile = file;
    };
    c.closePreview = function () { c.previewFile = null; };
    c.previewImages = function () {
        if (!c.previewFile) return [];
        var list = c.visibleFiles().filter(c.isImage);
        return list.some(function (f) { return f.sys_id === c.previewFile.sys_id; }) ? list : [c.previewFile];
    };
    c.previewStep = function (dir) {
        var list = c.previewImages();
        if (list.length < 2) return;
        var idx = 0;
        for (var i = 0; i < list.length; i++) if (list[i].sys_id === c.previewFile.sys_id) idx = i;
        c.previewFile = list[(idx + dir + list.length) % list.length];
    };

