    };
    var _colorMap = {
        'fa fa-file-image-o': 'fm-icon-image', 'fa fa-file-pdf-o': 'fm-icon-pdf', 'fa fa-file-word-o': 'fm-icon-word',
        'fa fa-file-excel-o': 'fm-icon-excel', 'fa fa-file-powerpoint-o': 'fm-icon-ppt', 'fa fa-file-zip-o': 'fm-icon-zip',
        'fa fa-file-audio-o': 'fm-icon-audio', 'fa fa-file-video-o': 'fm-icon-video', 'fa fa-file-code-o': 'fm-icon-code',
        'fa fa-file-text-o': 'fm-icon-text'
    };
    c.getFileIcon = function (file) { return file ? (_iconMap[(file.file_extension || '').toLowerCase()] || 'fa fa-file-o') : 'fa fa-file-o'; };
    c.getFileIconColor = function (file) { return _colorMap[c.getFileIcon(file)] || 'fm-icon-default'; };

    /* ===================================================
       SELECTION
    =================================================== */
    c.visibleFiles = function () {
        if (c.view === 'allfiles') return c.allFilesFiltered();
        if (c.view === 'files') return c.filesInCurrentFolder().filter(c.searchFiles);
        return [];
    };
    c.selectedCount = function () { return c.visibleFiles().filter(function (f) { return f._selected; }).length; };
    c.toggleSelectAll = function () { c.visibleFiles().forEach(function (f) { f._selected = c.allSelected; }); };
    c.selectAllVisible = function () { c.allSelected = true; c.toggleSelectAll(); };
    c.onFileSelect = function () {
        var list = c.visibleFiles();
        c.allSelected = list.length > 0 && list.every(function (f) { return f._selected; });
    };
    c.clearSelection = function () { _clearSelection(); };

    /* ===================================================
       CONTEXT MENU
    =================================================== */
    c.openContextMenu = function (e, item, type) {
        e.preventDefault(); e.stopPropagation();
        if (c.pickerMode) return;
        var x = e.clientX || 0, y = e.clientY || 0;
        if (x + 200 > window.innerWidth) x = window.innerWidth - 210;
        if (y + 260 > window.innerHeight) y = window.innerHeight - 270;
        c.contextMenu = { show: true, x: x, y: y, item: item, type: type };
    };
    c.closeContextMenu = function () {
        if (c.contextMenu.show) { c.contextMenu.show = false; c.contextMenu.item = null; }
    };
    c.openMenuFromButton = function ($event, item, type) {
        $event.preventDefault(); $event.stopPropagation();
        if (c.pickerMode || !item) return;
        if (c.contextMenu.show && c.contextMenu.item === item) { c.closeContextMenu(); return; }
        var rect = ($event.currentTarget || $event.target).getBoundingClientRect();
        var x = rect.right - 200, y = rect.bottom + 4;
        if (x < 10) x = 10;
        if (y + 260 > window.innerHeight) y = rect.top - 264;
        if (y < 10) y = 10;
        c.contextMenu = { show: true, x: x, y: y, item: item, type: type };
    };

    c.formatBytes = function (bytes) {
        bytes = parseInt(bytes, 10) || 0;
        if (bytes === 0) return '0 B';
        if (bytes < 1024) return bytes + ' B';
        if (bytes < 1048576) return (bytes / 1024).toFixed(1) + ' KB';
        if (bytes < 1073741824) return (bytes / 1048576).toFixed(1) + ' MB';
        return (bytes / 1073741824).toFixed(2) + ' GB';
    };

    /* ===================================================
       KEYBOARD
    =================================================== */
    c.anyModalOpen = function () {
        return !!(c.showFolderModal || c.showEditFileModal || c.showRenameFileModal ||
            c.showUploadFolderPicker || c.showAddToFolderModal || c.showNicknameModal || c.confirmModal.show || c.previewFile);
    };

    c.onKeyDown = function (e) {
        var key = e.key || '';
        var tag = ((e.target && e.target.tagName) || '').toLowerCase();
        var typing = tag === 'input' || tag === 'textarea' || tag === 'select';

        if (key === 'Escape' || e.keyCode === 27) {
            if (c.contextMenu.show) { c.closeContextMenu(); return; }
            if (c.previewFile) { c.closePreview(); return; }
            if (c.showNicknameModal) { c.cancelNicknameUpload(); return; }
            if (c.confirmModal.show) { c.confirmModal.show = false; return; }
            if (c.showAddToFolderModal) { c.closeAddToFolder(); return; }
            if (c.showRenameFileModal) { c.showRenameFileModal = false; return; }
            if (c.showEditFileModal) { c.showEditFileModal = false; return; }
            if (c.showFolderModal) { c.closeFolderModal(); return; }
            if (c.showUploadFolderPicker) { c.showUploadFolderPicker = false; return; }
            if (typing && e.target.id === 'fmSearch') { c.searchText = ''; e.target.blur(); return; }
            if (c.selectedCount() > 0) { c.clearSelection(); return; }
            return;
        }
        if (c.previewFile) {
            if (key === 'ArrowLeft') { c.previewStep(-1); e.preventDefault(); }
            if (key === 'ArrowRight') { c.previewStep(1); e.preventDefault(); }
            return;
        }
        if (typing || c.anyModalOpen()) return;

        if (key === '/' || ((e.ctrlKey || e.metaKey) && (key === 'k' || key === 'K'))) {
            var s = document.getElementById('fmSearch');
            if (s) { s.focus(); e.preventDefault(); }
        } else if ((e.ctrlKey || e.metaKey) && (key === 'a' || key === 'A')) {
            if (c.visibleFiles().length) { c.selectAllVisible(); e.preventDefault(); }
        } else if (key === 'Delete' && !c.pickerMode) {
            if (c.selectedCount() > 0 && c.canDeleteSelected()) { c.confirmDeleteSelected(); e.preventDefault(); }
        }
    };

    /* ===================================================
       PRIVATE HELPERS
    =================================================== */
    function _clearAlerts() { c.message = ''; c.error = ''; c.undo = null; }
    function _clearSelection() {
        c.allSelected = false;
        _allFiles().forEach(function (f) { f._selected = false; });
    }

    /* ===================================================
       BROWSER BACK / FORWARD
    =================================================== */
    function _navKey(s) { return (s.view || '') + '|' + (s.currentFolder || ''); }
    function _navSnapshot() {
        return { view: c.view, currentFolder: c.currentFolder, currentFolderName: c.currentFolderName, breadcrumb: angular.copy(c.breadcrumb) };
    }
    var _lastNavKey = _navKey(_navSnapshot());

    function _applyNavSnapshot(s) {
        _lastNavKey = _navKey(s);
        c.view = s.view || 'allfiles';
        c.currentFolder = s.currentFolder || '';
        c.currentFolderName = s.currentFolderName || '';
        c.breadcrumb = angular.copy(s.breadcrumb || []);
        c.searchText = '';
        _clearAlerts(); _clearSelection(); c.closeContextMenu();
        c.previewFile = null;
    }

    if (!c.pickerMode && window.history && history.pushState) {
        try {
            history.replaceState(angular.extend({}, history.state || {}, { fmNavPublic: _navSnapshot() }), document.title, window.location.href);
        } catch (e) { }

        $scope.$watch(function () { return _navKey(c); }, function (key) {
            if (key === _lastNavKey) return;
            _lastNavKey = key;
            try {
                history.pushState(angular.extend({}, history.state || {}, { fmNavPublic: _navSnapshot() }), document.title, window.location.href);
            } catch (e) { }
        });

        var _onPopState = function (ev) {
            var st = ev && ev.state;
            if (st && st.fmNavPublic) $scope.$evalAsync(function () { _applyNavSnapshot(st.fmNavPublic); });
        };
        window.addEventListener('popstate', _onPopState);
        $scope.$on('$destroy', function () { window.removeEventListener('popstate', _onPopState); });
    }

    /* Fallback listener binding if script is pasted directly into Client Controller without Link Function */
    $timeout(function () {
        var root = (typeof $element !== 'undefined' && $element && $element[0]) || document.querySelector('.fm-app') || document;
        if (!root || root.__fmCtrlBound) return;
        root.__fmCtrlBound = true;

        root.addEventListener('click', function (e) {
            var t = e.target;
            if (t && t.getAttribute && t.getAttribute('data-fm-input')) {
                try { t.value = ''; } catch (ex) { }
            }
        });

        root.addEventListener('change', function (e) {
            var t = e.target;
            var kind = t && t.getAttribute && t.getAttribute('data-fm-input');
            if (!kind) return;
            var files = [];
            if (t.files) {
                for (var i = 0; i < t.files.length; i++) files.push(t.files[i]);
            }
            if (!files.length) return;
            $timeout(function () {
                if (kind === 'folder') c.onFolderUploadSelected(files);
                else if (kind === 'direct') c.onDirectFilesSelected(files);
                else if (kind === 'picker') c.onPickerFilesSelected(files);
            });
        });
    }, 100);
};

/* =====================================================
   LINK FUNCTION
===================================================== */
api.link = function ($scope, element) {
    var rootEl = element[0];

    function safeApply(fn) {
        if ($scope.$$phase || ($scope.$root && $scope.$root.$$phase)) { if (fn) fn(); }
        else $scope.$apply(fn);
    }

    /* File inputs */
    rootEl.addEventListener('click', function (e) {
        var t = e.target;
        if (t && t.getAttribute && t.getAttribute('data-fm-input')) {
            try { t.value = ''; } catch (ex) { }
        }
    });

    rootEl.addEventListener('change', function (e) {
        var t = e.target;
        var kind = t && t.getAttribute && t.getAttribute('data-fm-input');
        if (!kind) return;
        var files = [];
        if (t.files) {
            for (var i = 0; i < t.files.length; i++) {
                files.push(t.files[i]);
            }
        }
        if (!files.length) return;
        safeApply(function () {
            var c = $scope.c;
            if (kind === 'folder') c.onFolderUploadSelected(files);
            else if (kind === 'direct') c.onDirectFilesSelected(files);
            else if (kind === 'picker') c.onPickerFilesSelected(files);
        });
    });

    /* Right-click */
    rootEl.addEventListener('contextmenu', function (ev) {
        var target = ev.target.closest('[fm-context-id]');
        if (!target) return;
        ev.preventDefault();
        var type = target.getAttribute('fm-context-type'), id = target.getAttribute('fm-context-id');
        safeApply(function () {
            var item = $scope.c.findItem(type, id);
            if (item) $scope.c.openContextMenu(ev, item, type);
        });
    });

    /* Drag & drop */
    function hasFiles(e) {
        var types = e.dataTransfer && e.dataTransfer.types;
        if (!types) return false;
        for (var i = 0; i < types.length; i++) if (types[i] === 'Files') return true;
        return false;
    }
    function prevent(e) { e.preventDefault(); e.stopPropagation(); }
    function dropFolderOf(e) {
        var el = e.target.closest && e.target.closest('[fm-drop-folder]');
        return (el && el.getAttribute('fm-drop-folder')) ? el : null;
    }

    rootEl.addEventListener('dragover', function (e) {
        if (!hasFiles(e)) return;
        var zone = e.target.closest('[fm-drop-zone]'), card = dropFolderOf(e);
        e.preventDefault();
        if (zone || card) {
            e.stopPropagation();
            e.dataTransfer.dropEffect = 'copy';
            if (zone) safeApply(function () { $scope.c.dragOver = true; });
            if (card) card.classList.add('fm-drag-over');
        }
    });
    rootEl.addEventListener('dragleave', function (e) {
        var zone = e.target.closest('[fm-drop-zone]');
        if (zone && !zone.contains(e.relatedTarget)) safeApply(function () { $scope.c.dragOver = false; });
        var card = dropFolderOf(e);
        if (card && !card.contains(e.relatedTarget)) card.classList.remove('fm-drag-over');
    });
    rootEl.addEventListener('drop', function (e) {
        if (!hasFiles(e)) return;
        e.preventDefault();
        var zone = e.target.closest('[fm-drop-zone]'), card = dropFolderOf(e);
        var files = e.dataTransfer && e.dataTransfer.files;
        if (card) {
            prevent(e);
            card.classList.remove('fm-drag-over');
            var folderId = card.getAttribute('fm-drop-folder');
            if (files && files.length) safeApply(function () { $scope.c.uploadToFolder(files, folderId); });
        } else if (zone) {
            prevent(e);
            safeApply(function () { $scope.c.dragOver = false; });
            if (files && files.length && $scope.c.currentFolder && $scope.c.currentFolderCanEdit()) {
                safeApply(function () { $scope.c.onDirectFilesSelected(files); });
            }
        }
    });

    /* Keyboard */
    function onDocKey(e) { if ($scope.c) safeApply(function () { $scope.c.onKeyDown(e); }); }
    document.addEventListener('keydown', onDocKey);

    function closeMenuOnScroll() {
        if ($scope.c && $scope.c.contextMenu && $scope.c.contextMenu.show) safeApply(function () { $scope.c.closeContextMenu(); });
    }
    window.addEventListener('scroll', closeMenuOnScroll, true);
    window.addEventListener('resize', closeMenuOnScroll);

    $scope.$on('$destroy', function () {
        document.removeEventListener('keydown', onDocKey);
        window.removeEventListener('scroll', closeMenuOnScroll, true);
        window.removeEventListener('resize', closeMenuOnScroll);
    });
};

sp_widget.css:
/* =========================================================
   FILE MANAGER - LIGHT PROFESSIONAL THEME (BLUE)
   Use this SAME css in BOTH widgets (private + public).
========================================================= */

/* ---------- Design tokens ---------- */
.fm-app {
    --fm-bg: #f6f8fc;
    --fm-surface: #ffffff;
    --fm-surface-2: #f8fafc;
    --fm-border: #e6ebf2;
    --fm-border-strong: #d5dde8;
    --fm-text: #1f2a3d;
    --fm-text-strong: #0f1b2d;
    --fm-muted: #64748b;
    --fm-faint: #94a3b8;
    --fm-primary: #2563eb;
    --fm-primary-600: #1d4ed8;
    --fm-primary-50: #eff4ff;
    --fm-primary-100: #dbe7ff;
    --fm-success: #16a34a;
    --fm-danger: #dc2626;
    --fm-radius: 12px;
    --fm-radius-lg: 16px;
    --fm-shadow-sm: 0 1px 2px rgba(16, 24, 40, 0.05);
    --fm-shadow: 0 4px 14px rgba(16, 24, 40, 0.06);
    --fm-shadow-lg: 0 14px 36px rgba(16, 24, 40, 0.12);
    --fm-ease: cubic-bezier(0.2, 0.7, 0.2, 1);
}

/* ---------- Base ---------- */
.fm-app {
    display: flex;
    width: 100%;
    min-height: 800px;
    background: var(--fm-bg);
    color: var(--fm-text);
    font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
    position: relative;
    box-sizing: border-box;
    -webkit-font-smoothing: antialiased;
}

.fm-app * { box-sizing: border-box; }

.fm-app button,
.fm-app input,
.fm-app select,
.fm-app textarea { font-family: inherit; }

.fm-app a:focus-visible,
.fm-app button:focus-visible,
.fm-app select:focus-visible,
.fm-app input:focus-visible,
.fm-app tr:focus-visible,
.fm-app [tabindex]:focus-visible {
    outline: 2px solid var(--fm-primary);
    outline-offset: 2px;
}

.fm-app ::-webkit-scrollbar { width: 8px; height: 8px; }
.fm-app ::-webkit-scrollbar-thumb { background: #d3dbe7; border-radius: 9999px; }
.fm-app ::-webkit-scrollbar-thumb:hover { background: #b8c4d4; }

/* ---------- Picker mode ---------- */
.fm-picker .fm-toolbar-actions,
.fm-picker .fm-card-menu,
.fm-picker .fm-context-menu,
.fm-picker .fm-empty .fm-button,
.fm-picker .fm-more-btn,
.fm-picker .fm-drop-zone { display: none !important; }

.fm-picker .fm-table tbody tr { cursor: pointer; user-select: none; }

.fm-picker-banner {
    margin: 0 0 16px;
    padding: 12px 18px;
    background: var(--fm-primary-50);
    border: 1px solid var(--fm-primary-100);
    border-radius: var(--fm-radius);
    font-size: 13px;
    color: var(--fm-primary-600);
    display: flex;
    align-items: center;
    gap: 10px;
    font-weight: 500;
}

/* =========================================================
   SIDEBAR
========================================================= */
.fm-sidebar {
    width: 250px;
    min-width: 250px;
    background: var(--fm-surface);
    color: var(--fm-muted);
    display: flex;
    flex-direction: column;
    min-height: 800px;
    flex-shrink: 0;
    position: relative;
    border-right: 1px solid var(--fm-border);
}

.fm-logo {
    height: 76px;
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 0 22px;
    font-size: 18px;
    font-weight: 700;
    color: var(--fm-text-strong);
    cursor: pointer;
    user-select: none;
    letter-spacing: -0.2px;
}

.fm-logo-icon {
    width: 38px;
    height: 38px;
    border-radius: 11px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: linear-gradient(135deg, #3b82f6 0%, #2563eb 100%);
    color: #fff;
    font-size: 17px;
    flex-shrink: 0;
    box-shadow: 0 4px 12px rgba(37, 99, 235, 0.28);
    transition: transform 0.3s var(--fm-ease);
}

.fm-logo:hover .fm-logo-icon { transform: rotate(-8deg) scale(1.06); }

/* Private / Public switch (two links) */
.fm-privacy-switch {
    margin: 0 16px 14px;
    padding: 3px;
    background: #eef2f8;
    border: 1px solid var(--fm-border);
    border-radius: 9999px;
    display: flex;
    gap: 3px;
}

.fm-privacy-btn {
    flex: 1;
    height: 32px;
    border: none;
    background: transparent;
    color: var(--fm-muted);
    font-size: 12px;
    font-weight: 600;
    border-radius: 9999px;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    text-decoration: none;
    transition: all 0.2s var(--fm-ease);
}

a.fm-privacy-btn,
a.fm-privacy-btn:hover,
a.fm-privacy-btn:focus { text-decoration: none; }

.fm-privacy-btn:hover { color: var(--fm-text-strong); }

.fm-privacy-btn.active {
    background: #fff;
    color: var(--fm-primary-600);
    box-shadow: 0 1px 4px rgba(16, 24, 40, 0.12);
}

.fm-check-mark { font-size: 10px; margin-left: 2px; }

/* Menu */
.fm-menu { padding: 10px 14px; flex: 1; }

.fm-menu-label {
    color: var(--fm-faint);
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.9px;
    padding: 0 14px;
    margin-bottom: 8px;
    text-transform: uppercase;
}

.fm-menu-spaced { margin-top: 22px; }

.fm-menu a {
    position: relative;
    display: flex;
    align-items: center;
    gap: 12px;
    height: 42px;
    padding: 0 14px;
    margin-bottom: 3px;
    border-radius: 10px;
    color: var(--fm-muted);
    font-size: 13px;
    font-weight: 500;
    text-decoration: none;
    cursor: pointer;
    transition: background 0.18s ease, color 0.18s ease, transform 0.18s var(--fm-ease);
    user-select: none;
}

.fm-menu a i {
    width: 20px;
    font-size: 15px;
    text-align: center;
    flex-shrink: 0;
    transition: transform 0.18s var(--fm-ease);
}

.fm-menu a:hover { background: #f1f5fb; color: var(--fm-text-strong); }
.fm-menu a:hover i { transform: scale(1.12); }
.fm-menu a:active { transform: scale(0.98); }

.fm-menu a.active {
    background: var(--fm-primary-50);
    color: var(--fm-primary-600);
    font-weight: 600;
}

.fm-menu a.active::before {
    content: "";
    position: absolute;
    left: -14px;
    top: 9px;
    bottom: 9px;
    width: 3px;
    border-radius: 0 3px 3px 0;
    background: var(--fm-primary);
}

.fm-menu a.active i { color: var(--fm-primary); }

.fm-count-pill {
    margin-left: auto;
    padding: 2px 8px;
    border-radius: 9999px;
    background: #eef2f8;
    color: var(--fm-muted);
    font-size: 11px;
    font-weight: 600;
}

.fm-menu a.active .fm-count-pill { background: #fff; color: var(--fm-primary-600); }

.fm-badge {
    margin-left: auto;
    min-width: 20px;
    height: 20px;
    padding: 0 6px;
    border-radius: 10px;
    background: #fee2e2;
    color: #b91c1c;
    font-size: 11px;
    font-weight: 700;
    display: flex;
    align-items: center;
    justify-content: center;
}

/* Sidebar storage */
.fm-sidebar-storage {
    margin: 14px 4px 6px;
    padding: 12px 14px;
    border-radius: 12px;
    background: var(--fm-surface-2);
    border: 1px solid var(--fm-border);
    cursor: pointer;
    transition: all 0.18s ease;
}

.fm-sidebar-storage:hover { border-color: var(--fm-primary-100); background: var(--fm-primary-50); }

.fm-storage-bar-track {
    width: 100%;
    height: 6px;
    background: #e3e9f2;
    border-radius: 9999px;
    overflow: hidden;
    margin-bottom: 8px;
}

.fm-storage-bar-fill {
    height: 100%;
    border-radius: 9999px;
    background: linear-gradient(90deg, #60a5fa, #2563eb);
    transition: width 0.6s var(--fm-ease);
}

.fm-storage-legend { font-size: 11px; color: var(--fm-muted); font-weight: 500; }

/* Bottom art */
.fm-sidebar-bottom-art {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 14px 10px 20px;
    margin-top: auto;
    overflow: hidden;
}

.fm-art-glow {
    position: absolute;
    width: 110px;
    height: 110px;
    border-radius: 50%;
    background: radial-gradient(circle, rgba(96, 165, 250, 0.22) 0%, transparent 70%);
    pointer-events: none;
}

.fm-art-svg {
    width: 110px;
    height: 80px;
    position: relative;
    z-index: 1;
    filter: drop-shadow(0 6px 12px rgba(37, 99, 235, 0.18));
    animation: fm-float 5s ease-in-out infinite;
}

@keyframes fm-float {
    0%, 100% { transform: translateY(0); }
    50% { transform: translateY(-5px); }
}

.fm-sidebar-upload { display: none; }

/* =========================================================
   MAIN
========================================================= */
.fm-main {
    flex: 1;
    min-width: 0;
    padding: 24px 34px 40px;
    background: var(--fm-bg);
    display: flex;
    flex-direction: column;
    position: relative;
}

.fm-main > section { animation: fm-view-in 0.28s var(--fm-ease); }

@keyframes fm-view-in {
    from { opacity: 0; transform: translateY(6px); }
    to { opacity: 1; transform: none; }
}

.fm-loading-bar {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 3px;
    overflow: hidden;
    background: var(--fm-primary-100);
    z-index: 10;
}

.fm-loading-bar:after {
    content: "";
    position: absolute;
    top: 0;
    bottom: 0;
    width: 35%;
    background: var(--fm-primary);
    animation: fm-load 1s ease-in-out infinite;
}

@keyframes fm-load {
    from { left: -35%; }
    to { left: 100%; }
}

/* ---------- Header ---------- */
.fm-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    min-height: 52px;
    margin-bottom: 22px;
    flex-wrap: wrap;
}

.fm-header-title h2 {
    margin: 0;
    font-size: 24px;
    font-weight: 700;
    color: var(--fm-text-strong);
    letter-spacing: -0.4px;
}

.fm-header-actions { display: flex; align-items: center; gap: 10px; flex-shrink: 0; }

.fm-search-pill {
    display: flex;
    align-items: center;
    gap: 10px;
    width: 310px;
    height: 42px;
    padding: 0 14px;
    border: 1px solid var(--fm-border);
    border-radius: 9999px;
    background: var(--fm-surface);
    box-shadow: var(--fm-shadow-sm);
    transition: width 0.25s var(--fm-ease), border-color 0.2s, box-shadow 0.2s;
}

.fm-search-pill:hover { border-color: var(--fm-border-strong); }

.fm-search-pill:focus-within {
    border-color: var(--fm-primary);
    box-shadow: 0 0 0 4px rgba(37, 99, 235, 0.12);
    width: 360px;
}

.fm-search-pill i.fa-search { color: var(--fm-faint); font-size: 13px; flex-shrink: 0; }
.fm-search-pill:focus-within i.fa-search { color: var(--fm-primary); }

.fm-search-pill input {
    width: 100%;
    min-width: 0;
    border: none !important;
    outline: none !important;
    box-shadow: none !important;
    background: transparent;
    font-size: 13px;
    color: var(--fm-text);
}

.fm-search-pill input::placeholder { color: var(--fm-faint); }

.fm-search-clear {
    border: none;
    background: #eef2f8;
    color: var(--fm-muted);
    width: 20px;
    height: 20px;
    border-radius: 50%;
    font-size: 10px;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    transition: background 0.15s;
}

.fm-search-clear:hover { background: #dfe6f1; color: var(--fm-text-strong); }

.fm-shortcut-badge {
    padding: 3px 7px;
    background: var(--fm-surface-2);
    border: 1px solid var(--fm-border);
    border-radius: 6px;
    font-size: 10px;
    font-weight: 700;
    color: var(--fm-muted);
    white-space: nowrap;
}

.fm-icon-circle-btn {
    width: 42px;
    height: 42px;
    border: 1px solid var(--fm-border);
    border-radius: 50%;
    background: var(--fm-surface);
    color: var(--fm-muted);
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 15px;
    box-shadow: var(--fm-shadow-sm);
    position: relative;
    transition: all 0.18s var(--fm-ease);
}

.fm-icon-circle-btn:hover {
    color: var(--fm-primary);
    background: var(--fm-primary-50);
    border-color: var(--fm-primary-100);
    transform: translateY(-1px);
}

.fm-icon-circle-btn:active { transform: scale(0.94); }

.fm-user-avatar-btn {
    width: 42px;
    height: 42px;
    border-radius: 50%;
    background: linear-gradient(135deg, #6366f1 0%, #8b5cf6 100%);
    color: #fff;
    font-size: 13px;
    font-weight: 700;
    display: flex;
    align-items: center;
    justify-content: center;
    box-shadow: 0 3px 10px rgba(99, 102, 241, 0.25);
    user-select: none;
    cursor: default;
}

.fm-icon-circle-btn.fm-spinning i { animation: fm-spin 0.8s linear infinite; }

@keyframes fm-spin { to { transform: rotate(360deg); } }

/* ---------- Breadcrumb ---------- */
.fm-breadcrumb {
    display: flex;
    align-items: center;
    gap: 8px;
    margin-bottom: 18px;
    font-size: 13px;
    color: var(--fm-muted);
    flex-wrap: wrap;
}

.fm-breadcrumb a {
    color: var(--fm-primary);
    text-decoration: none;
    cursor: pointer;
    font-weight: 500;
    padding: 2px 6px;
    border-radius: 6px;
    transition: background 0.15s;
}

.fm-breadcrumb a:hover { background: var(--fm-primary-50); }
.fm-breadcrumb-sep { color: #c3cddb; font-size: 12px; }
.fm-breadcrumb-current { color: var(--fm-text-strong); font-weight: 700; padding: 2px 6px; }

/* =========================================================
   HERO + STATS (private home)
========================================================= */
.fm-hero-banner {
    display: flex;
    align-items: center;
    justify-content: space-between;
    min-height: 120px;
    padding: 22px 32px;
    border-radius: 18px;
    background: linear-gradient(105deg, #eaf2ff 0%, #f1edff 55%, #fdf0f7 100%);
    border: 1px solid #e3e9f7;
    box-shadow: var(--fm-shadow-sm);
    position: relative;
    overflow: hidden;
}

.fm-hero-content h3 { margin: 0 0 6px; font-size: 22px; font-weight: 700; color: var(--fm-text-strong); letter-spacing: -0.3px; }
.fm-hero-content p { margin: 0; font-size: 13px; color: var(--fm-muted); font-weight: 500; }

.fm-hero-graphic { width: 220px; height: 100px; flex-shrink: 0; display: flex; align-items: center; justify-content: flex-end; }
.fm-hero-graphic svg { max-width: 100%; max-height: 100%; }

.fm-stats {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 16px;
    margin-top: 20px;
}

.fm-stat-card {
    display: flex;
    align-items: center;
    gap: 14px;
    min-height: 94px;
    padding: 18px 20px;
    border-radius: var(--fm-radius-lg);
    background: var(--fm-surface);
    border: 1px solid var(--fm-border);
    position: relative;
    overflow: hidden;
    box-shadow: var(--fm-shadow-sm);
    transition: transform 0.2s var(--fm-ease), box-shadow 0.2s ease, border-color 0.2s ease;
    cursor: default;
}

.fm-stat-card::after {
    content: "";
    position: absolute;
    left: 0;
    right: 0;
    bottom: 0;
    height: 3px;
    background: var(--accent, var(--fm-primary));
    transform: scaleX(0);
    transform-origin: left;
    transition: transform 0.3s var(--fm-ease);
}

.fm-stat-card.fm-clickable { cursor: pointer; }
.fm-stat-card.fm-clickable:hover { transform: translateY(-3px); box-shadow: var(--fm-shadow); border-color: var(--fm-border-strong); }
.fm-stat-card.fm-clickable:hover::after { transform: scaleX(1); }
.fm-stat-card.fm-clickable:active { transform: translateY(-1px) scale(0.99); }

.fm-stat-card.card-blue { --accent: #3b82f6; background: linear-gradient(135deg, #ffffff 40%, #f0f7ff 100%); }
.fm-stat-card.card-purple { --accent: #8b5cf6; background: linear-gradient(135deg, #ffffff 40%, #f6f1ff 100%); }
.fm-stat-card.card-green { --accent: #22c55e; background: linear-gradient(135deg, #ffffff 40%, #effcf4 100%); }
.fm-stat-card.card-orange { --accent: #f59e0b; background: linear-gradient(135deg, #ffffff 40%, #fff8eb 100%); }

.fm-stat-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 44px;
    height: 44px;
    min-width: 44px;
    border-radius: 12px;
    font-size: 18px;
    flex-shrink: 0;
    transition: transform 0.25s var(--fm-ease);
}

.fm-stat-card:hover .fm-stat-icon { transform: scale(1.08) rotate(-4deg); }

.fm-stat-icon.blue { background: #dbeafe; color: #2563eb; }
.fm-stat-icon.purple { background: #ede9fe; color: #7c3aed; }
.fm-stat-icon.green { background: #dcfce7; color: #16a34a; }
.fm-stat-icon.orange { background: #fef3c7; color: #d97706; }

.fm-stat-text { flex: 1; min-width: 0; }
.fm-stat-text span { display: block; color: var(--fm-muted); font-size: 12px; font-weight: 600; margin-bottom: 2px; }
.fm-stat-text strong { display: block; color: var(--fm-text-strong); font-size: 26px; font-weight: 700; letter-spacing: -0.5px; }

.fm-stat-decor { width: 52px; height: 44px; flex-shrink: 0; display: flex; align-items: center; justify-content: center; opacity: 0.8; }
.fm-stat-decor svg { width: 100%; height: 100%; }

/* ---------- Recent ---------- */
.fm-recent-section { margin-top: 28px; }

.fm-recent-header-bar { display: flex; align-items: center; justify-content: space-between; margin-bottom: 14px; }
.fm-recent-title { display: flex; align-items: center; gap: 8px; color: var(--fm-text-strong); }
.fm-recent-title i { font-size: 16px; color: var(--fm-primary); }

.fm-recent-title h4,
.fm-recent-header-bar h4 { margin: 0; font-size: 16px; font-weight: 700; color: var(--fm-text-strong); letter-spacing: -0.2px; }

.fm-view-switch {
    display: flex;
    align-items: center;
    gap: 3px;
    background: var(--fm-surface);
    border: 1px solid var(--fm-border);
    border-radius: 10px;
    padding: 3px;
    box-shadow: var(--fm-shadow-sm);
}

.fm-view-btn {
    width: 32px;
    height: 32px;
    border: none;
    background: transparent;
    border-radius: 8px;
    color: var(--fm-muted);
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 14px;
    transition: all 0.15s;
}

.fm-view-btn:hover { color: var(--fm-primary); background: var(--fm-surface-2); }
.fm-view-btn.active { background: var(--fm-primary-50); color: var(--fm-primary); }

/* =========================================================
   TABLE
========================================================= */
.fm-table-card {
    background: var(--fm-surface);
    border-radius: var(--fm-radius-lg);
    border: 1px solid var(--fm-border);
    box-shadow: var(--fm-shadow-sm);
    overflow-x: auto;
    overflow-y: hidden;
    width: 100%;
}

.fm-table { width: 100%; border-collapse: collapse; min-width: 580px; }

.fm-table th {
    padding: 13px 20px;
    text-align: left;
    background: var(--fm-surface-2);
    border-bottom: 1px solid var(--fm-border);
    color: var(--fm-muted);
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.5px;
    text-transform: uppercase;
    white-space: nowrap;
    vertical-align: middle;
}

.fm-table th.fm-sortable { cursor: pointer; user-select: none; transition: color 0.15s; }
.fm-table th.fm-sortable:hover { color: var(--fm-primary); }

.fm-table td {
    padding: 12px 20px;
    border-bottom: 1px solid #f1f4f9;
    color: var(--fm-text);
    font-size: 13px;
    vertical-align: middle;
}

.fm-table tbody tr { cursor: pointer; transition: background 0.12s ease; }
.fm-table tbody tr:last-child td { border-bottom: none; }
.fm-table tbody tr:hover { background: #f5f8ff; }
.fm-table tbody tr.fm-row-selected { background: var(--fm-primary-50); box-shadow: inset 3px 0 0 var(--fm-primary); }

.fm-table input[type="checkbox"] { width: 16px; height: 16px; accent-color: var(--fm-primary); cursor: pointer; }

.fm-table tbody tr .fm-more-btn { opacity: 0.55; }
.fm-table tbody tr:hover .fm-more-btn { opacity: 1; }

.fm-file-cell { display: flex; align-items: center; gap: 12px; min-width: 0; }

.fm-file-icon-box {
    width: 38px;
    height: 38px;
    border-radius: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 17px;
    flex-shrink: 0;
    transition: transform 0.2s var(--fm-ease);
}

tr:hover .fm-file-icon-box,
.fm-file-card:hover .fm-file-card-preview { transform: scale(1.07); }

.fm-file-title {
    font-weight: 600;
    color: var(--fm-text-strong);
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    max-width: 320px;
}

.fm-text-muted { color: var(--fm-muted); font-size: 13px; }

/* file name + nickname badge */
.fm-file-name-wrap { display: flex; flex-direction: column; gap: 3px; min-width: 0; }

.fm-nick {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    width: fit-content;
    max-width: 260px;
    padding: 1px 9px;
    border-radius: 9999px;
    background: var(--fm-primary-50);
    color: var(--fm-primary-600);
    border: 1px solid var(--fm-primary-100);
    font-size: 11px;
    font-weight: 600;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.fm-nick i { font-size: 10px; }

/* File-type colors */
.fm-icon-image { background: #dcfce7; color: #16a34a; }
.fm-icon-pdf { background: #fee2e2; color: #dc2626; }
.fm-icon-word { background: #dbeafe; color: #2563eb; }
.fm-icon-excel { background: #d1fae5; color: #059669; }
.fm-icon-ppt { background: #ffedd5; color: #ea580c; }
.fm-icon-zip { background: #fef3c7; color: #d97706; }
.fm-icon-audio { background: #e0e7ff; color: #4f46e5; }
.fm-icon-video { background: #fae8ff; color: #c026d3; }
.fm-icon-code { background: #f3e8ff; color: #9333ea; }
.fm-icon-text { background: #f1f5f9; color: #475569; }
.fm-icon-default { background: #f1f5f9; color: #64748b; }

/* Three-dots */
.fm-more-btn {
    width: 34px;
    height: 34px;
    border: 1px solid transparent;
    border-radius: 50%;
    background: transparent;
    color: var(--fm-muted);
    font-size: 15px;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    transition: all 0.15s ease;
}

.fm-more-btn:hover { background: var(--fm-primary-50); border-color: var(--fm-primary-100); color: var(--fm-primary); }
.fm-more-btn:active { transform: scale(0.92); }

/* =========================================================
   CONTEXT MENU
========================================================= */
.fm-context-menu {
    position: fixed;
    z-index: 99999;
    min-width: 210px;
    background: var(--fm-surface);
    border: 1px solid var(--fm-border);
    border-radius: 12px;
    box-shadow: var(--fm-shadow-lg);
    padding: 6px;
    animation: fm-pop-in 0.14s var(--fm-ease);
    transform-origin: top left;
}

@keyframes fm-pop-in {
    from { opacity: 0; transform: scale(0.95) translateY(-4px); }
    to { opacity: 1; transform: none; }
}

.fm-context-item {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 9px 12px;
    font-size: 13px;
    font-weight: 500;
    color: var(--fm-text);
    border-radius: 8px;
    cursor: pointer;
    transition: background 0.12s ease, color 0.12s ease, padding-left 0.15s var(--fm-ease);
}

.fm-context-item i { width: 16px; font-size: 14px; text-align: center; color: var(--fm-muted); transition: color 0.12s; }
.fm-context-item:hover { background: var(--fm-primary-50); color: var(--fm-primary-600); padding-left: 15px; }
.fm-context-item:hover i { color: var(--fm-primary); }
.fm-context-item.danger,
.fm-context-item.danger i { color: var(--fm-danger); }
.fm-context-item.danger:hover { background: #fef2f2; color: #b91c1c; }
.fm-context-divider { height: 1px; background: var(--fm-border); margin: 4px 6px; }

/* =========================================================
   GRID VIEWS
========================================================= */
.fm-file-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 14px; }

.fm-file-card {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 12px 14px;
    border-radius: 14px;
    background: var(--fm-surface);
    border: 1px solid var(--fm-border);
    box-shadow: var(--fm-shadow-sm);
    cursor: pointer;
    position: relative;
    transition: transform 0.2s var(--fm-ease), box-shadow 0.2s ease, border-color 0.2s ease;
}

.fm-file-card:hover { border-color: var(--fm-primary-100); transform: translateY(-3px); box-shadow: var(--fm-shadow); }
.fm-file-card.fm-row-selected { border-color: var(--fm-primary); background: var(--fm-primary-50); }

.fm-file-card-preview {
    width: 42px;
    height: 42px;
    border-radius: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 18px;
    flex-shrink: 0;
    transition: transform 0.2s var(--fm-ease);
}

.fm-file-card-info { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; }

.fm-file-card-info strong {
    font-size: 13px;
    color: var(--fm-text-strong);
    font-weight: 600;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.fm-file-card-info span { font-size: 11px; color: var(--fm-muted); }

.fm-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(250px, 1fr)); gap: 14px; }

.fm-folder-card {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    min-height: 84px;
    padding: 14px 16px;
    border: 1px solid var(--fm-border);
    border-radius: 14px;
    background: var(--fm-surface);
    box-shadow: var(--fm-shadow-sm);
    transition: transform 0.2s var(--fm-ease), box-shadow 0.2s ease, border-color 0.2s ease, background 0.2s;
}

.fm-folder-card:hover { border-color: var(--fm-primary-100); box-shadow: var(--fm-shadow); transform: translateY(-3px); }

.fm-folder-card.fm-drag-over {
    border: 2px dashed var(--fm-primary);
    background: var(--fm-primary-50);
    box-shadow: 0 0 0 4px rgba(37, 99, 235, 0.12);
    transform: scale(1.02);
}

.fm-folder-main { display: flex; align-items: center; gap: 12px; flex: 1; min-width: 0; cursor: pointer; }

.fm-folder-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 44px;
    height: 44px;
    min-width: 44px;
    border-radius: 12px;
    background: #fff7e6;
    color: #f59e0b;
    font-size: 20px;
    transition: transform 0.25s var(--fm-ease);
}

.fm-folder-card:hover .fm-folder-icon { transform: scale(1.08) rotate(-4deg); }

.fm-folder-icon.fm-color-orange { background: #fff4de; color: #f59e0b; }
.fm-folder-icon.fm-color-blue { background: #e5efff; color: #3b82f6; }
.fm-folder-icon.fm-color-purple { background: #efeaff; color: #8b5cf6; }
.fm-folder-icon.fm-color-green { background: #def7ea; color: #10b981; }
.fm-folder-icon.fm-color-pink { background: #fde7f3; color: #ec4899; }

.fm-color-text-orange { color: #f59e0b !important; }
.fm-color-text-blue { color: #3b82f6 !important; }
.fm-color-text-purple { color: #8b5cf6 !important; }
.fm-color-text-green { color: #10b981 !important; }
.fm-color-text-pink { color: #ec4899 !important; }

.fm-folder-chip.fm-chip-orange { background: #fff4de; color: #b45309; }
.fm-folder-chip.fm-chip-blue { background: #e5efff; color: #1d4ed8; }
.fm-folder-chip.fm-chip-purple { background: #efeaff; color: #6d28d9; }
.fm-folder-chip.fm-chip-green { background: #def7ea; color: #047857; }
.fm-folder-chip.fm-chip-pink { background: #fde7f3; color: #be185d; }

.fm-card-info { display: flex; flex-direction: column; min-width: 0; gap: 3px; }

.fm-card-info strong {
    color: var(--fm-text-strong);
    font-size: 13px;
    font-weight: 700;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.fm-card-info span { color: var(--fm-muted); font-size: 11px; }
.fm-card-menu { display: flex; gap: 4px; flex-shrink: 0; }

.fm-folder-chip {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 4px 10px;
    background: #fff4de;
    color: #b45309;
    border-radius: 8px;
    font-size: 12px;
    font-weight: 600;
    cursor: pointer;
    max-width: 180px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    transition: filter 0.15s, transform 0.15s;
}

.fm-folder-chip:hover { filter: brightness(0.96); transform: translateY(-1px); }

/* Folder color picker */
.fm-color-picker { display: flex; align-items: center; gap: 8px; margin: 8px 0 16px; flex-wrap: wrap; }

.fm-color-pill {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    padding: 6px 12px;
    border-radius: 9999px;
    background: var(--fm-surface-2);
    border: 1px solid var(--fm-border);
    cursor: pointer;
    transition: all 0.15s ease;
    user-select: none;
    font-size: 12px;
    font-weight: 500;
    color: #475569;
}

.fm-color-pill:hover { background: #f1f5f9; border-color: var(--fm-border-strong); transform: translateY(-1px); }

.fm-color-pill.selected {
    background: #fff;
    border-color: var(--fm-primary);
    box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.15);
    color: var(--fm-text-strong);
    font-weight: 600;
}

.fm-color-circle { width: 16px; height: 16px; border-radius: 50%; display: inline-flex; align-items: center; justify-content: center; flex-shrink: 0; }
.fm-color-circle i { color: #fff; font-size: 8px; }
.fm-color-name { line-height: 1; }

/* =========================================================
   BUTTONS & TOOLBARS
========================================================= */
.fm-button {
    position: relative;
    overflow: hidden;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    min-height: 38px;
    padding: 8px 16px;
    border: 1px solid var(--fm-border-strong);
    border-radius: 10px;
    background: var(--fm-surface);
    color: #475569;
    font-size: 13px;
    font-weight: 600;
    cursor: pointer;
    text-decoration: none;
    white-space: nowrap;
    box-shadow: var(--fm-shadow-sm);
    transition: background 0.15s, color 0.15s, border-color 0.15s, transform 0.15s var(--fm-ease), box-shadow 0.15s;
}

.fm-button:hover { background: var(--fm-surface-2); color: var(--fm-primary); border-color: var(--fm-primary-100); transform: translateY(-1px); box-shadow: var(--fm-shadow); }
.fm-button:active { transform: translateY(0) scale(0.98); }

.fm-button.fm-primary {
    color: #fff;
    background: linear-gradient(180deg, #3b82f6 0%, #2563eb 100%);
    border-color: #2563eb;
    box-shadow: 0 2px 8px rgba(37, 99, 235, 0.28);
}

.fm-button.fm-primary:hover { background: linear-gradient(180deg, #4b8df8 0%, #1d4ed8 100%); color: #fff; box-shadow: 0 6px 16px rgba(37, 99, 235, 0.32); }

.fm-button.fm-danger { color: #b91c1c; background: #fef2f2; border-color: #fecaca; box-shadow: none; }
.fm-button.fm-danger:hover { background: #fee2e2; border-color: #fca5a5; color: #991b1b; }

.fm-button.fm-danger-solid { color: #fff; background: var(--fm-danger); border-color: var(--fm-danger); }
.fm-button.fm-danger-solid:hover { background: #b91c1c; color: #fff; }

.fm-button:disabled,
.fm-button[disabled],
.fm-disabled { opacity: 0.5; cursor: not-allowed; pointer-events: none; }

.fm-back-btn {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 4px 8px 4px 0;
    margin-bottom: 8px;
    border: none;
    background: transparent;
    color: var(--fm-primary);
    font-size: 13px;
    font-weight: 600;
    cursor: pointer;
}

.fm-back-btn i { transition: transform 0.18s var(--fm-ease); }
.fm-back-btn:hover i { transform: translateX(-4px); }

.fm-toolbar { display: flex; align-items: center; justify-content: space-between; gap: 16px; margin-bottom: 18px; flex-wrap: wrap; }
.fm-toolbar p { margin: 0; font-size: 13px; color: var(--fm-muted); }
.fm-toolbar-actions { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }

.fm-type-filter {
    height: 38px;
    padding: 0 12px;
    border: 1px solid var(--fm-border-strong);
    border-radius: 10px;
    background: var(--fm-surface);
    font-size: 12px;
    color: #475569;
    cursor: pointer;
    transition: border-color 0.15s;
}

.fm-type-filter:hover { border-color: var(--fm-primary); }

.fm-subsection { margin-top: 24px; }
.fm-subsection h4 { font-size: 15px; font-weight: 700; margin: 0 0 14px; color: var(--fm-text-strong); }
.fm-section { margin-top: 24px; }
.fm-section-header h3 { margin: 0 0 12px; font-size: 16px; font-weight: 700; color: var(--fm-text-strong); }

/* =========================================================
   DROP ZONE, UPLOAD, EMPTY, SELECTION
========================================================= */
.fm-drop-zone {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 12px;
    height: 64px;
    margin-bottom: 18px;
    border: 2px dashed var(--fm-border-strong);
    border-radius: 14px;
    color: var(--fm-muted);
    font-size: 13px;
    background: var(--fm-surface);
    transition: all 0.2s ease;
}

.fm-drop-zone i { font-size: 24px; color: var(--fm-primary); transition: transform 0.25s var(--fm-ease); }
.fm-drop-zone:hover { border-color: #93b4f5; background: #fafcff; }
.fm-drop-zone.fm-drag-over { border-color: var(--fm-primary); background: var(--fm-primary-50); color: var(--fm-primary-600); }
.fm-drop-zone.fm-drag-over i { transform: translateY(-4px) scale(1.15); }

.fm-upload-progress {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 18px;
    padding: 12px 18px;
    background: var(--fm-surface);
    border: 1px solid var(--fm-border);
    border-radius: var(--fm-radius);
    font-size: 13px;
    color: #334155;
    box-shadow: var(--fm-shadow-sm);
}

.fm-upload-bar { flex: 1; height: 6px; background: #eef2f8; border-radius: 9999px; overflow: hidden; }

.fm-upload-fill {
    height: 100%;
    border-radius: 9999px;
    transition: width 0.3s ease;
    background: linear-gradient(90deg, #60a5fa, #2563eb, #60a5fa);
    background-size: 200% 100%;
    animation: fm-shimmer 1.4s linear infinite;
}

@keyframes fm-shimmer {
    from { background-position: 200% 0; }
    to { background-position: -200% 0; }
}

.fm-empty { padding: 48px 20px; text-align: center; color: var(--fm-faint); }

.fm-empty > i {
    display: block;
    margin: 0 auto 14px;
    width: 76px;
    height: 76px;
    line-height: 76px;
    border-radius: 50%;
    background: #eef3fb;
    font-size: 32px;
    color: #a9b9d2;
}

.fm-empty p { margin: 0 0 14px; font-size: 13px; }

.fm-selection-bar {
    position: sticky;
    bottom: 16px;
    z-index: 5;
    margin-top: 14px;
    display: flex;
    align-items: center;
    gap: 10px;
    flex-wrap: wrap;
    padding: 12px 16px;
    background: var(--fm-surface);
    border: 1px solid var(--fm-primary-100);
    border-radius: 14px;
    box-shadow: var(--fm-shadow-lg);
    animation: fm-rise 0.22s var(--fm-ease);
}

@keyframes fm-rise {
    from { opacity: 0; transform: translateY(10px); }
    to { opacity: 1; transform: none; }
}

.fm-selection-count { font-size: 13px; color: var(--fm-primary-600); font-weight: 700; margin-right: auto; }

/* =========================================================
   ALERTS
========================================================= */
.fm-alert {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 12px 16px;
    margin-bottom: 18px;
    border-radius: var(--fm-radius);
    font-size: 13px;
    font-weight: 500;
    animation: fm-rise 0.22s var(--fm-ease);
}

.fm-alert span { flex: 1; }

.fm-alert button {
    border: none;
    background: transparent;
    font-size: 20px;
    line-height: 1;
    cursor: pointer;
    color: inherit;
    opacity: 0.55;
    transition: opacity 0.15s;
}

.fm-alert button:hover { opacity: 1; }

.fm-alert .fm-undo-btn {
    font-size: 12px;
    font-weight: 700;
    opacity: 1;
    padding: 4px 10px;
    border: 1px solid currentColor;
    border-radius: 6px;
}

.fm-alert .fm-undo-btn:hover { background: rgba(255, 255, 255, 0.6); }

.fm-alert-success { background: #ecfdf3; color: #166534; border: 1px solid #c6f0d6; }
.fm-alert-error { background: #fef2f2; color: #991b1b; border: 1px solid #fcd0d0; }

/* =========================================================
   STORAGE VIEW
========================================================= */
.fm-storage-card {
    display: flex;
    align-items: center;
    gap: 20px;
    padding: 24px 28px;
    border: 1px solid var(--fm-border);
    border-radius: var(--fm-radius-lg);
    background: var(--fm-surface);
    box-shadow: var(--fm-shadow-sm);
    margin-bottom: 20px;
}

.fm-storage-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 54px;
    height: 54px;
    border-radius: 14px;
    background: var(--fm-primary-50);
    color: var(--fm-primary);
    font-size: 24px;
    flex-shrink: 0;
}

.fm-storage-card h3 { margin: 0 0 4px; font-size: 18px; color: var(--fm-text-strong); font-weight: 700; }
.fm-storage-card p { margin: 0; color: var(--fm-muted); font-size: 13px; }
.fm-storage-note { margin-top: 18px; color: var(--fm-faint); font-size: 12px; line-height: 1.6; }

.fm-ext-badge {
    display: inline-block;
    padding: 4px 10px;
    border-radius: 6px;
    background: #eef2f8;
    color: #475569;
    font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
}

.fm-usage-track { display: inline-block; vertical-align: middle; width: calc(100% - 52px); height: 8px; background: #eef2f8; border-radius: 9999px; overflow: hidden; }
.fm-usage-fill { height: 100%; background: linear-gradient(90deg, #60a5fa, #2563eb); border-radius: 9999px; transition: width 0.6s var(--fm-ease); }
.fm-usage-pct { display: inline-block; width: 44px; margin-left: 4px; font-size: 12px; color: var(--fm-muted); text-align: right; font-weight: 600; }

/* =========================================================
   PAGINATION, TABS, STATUS, RECYCLE
========================================================= */
.fm-pagination {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 14px;
    flex-wrap: wrap;
    padding: 12px 18px;
    margin-top: 14px;
    border-radius: var(--fm-radius);
    background: var(--fm-surface);
    border: 1px solid var(--fm-border);
    color: var(--fm-muted);
    font-size: 12px;
}

.fm-pagination-controls { display: flex; align-items: center; gap: 6px; }

.fm-pagination-controls button,
.fm-pagination-controls select {
    min-height: 32px;
    min-width: 32px;
    padding: 4px 10px;
    border: 1px solid var(--fm-border-strong);
    border-radius: 8px;
    background: var(--fm-surface);
    color: #475569;
    font-size: 12px;
    font-weight: 600;
    transition: all 0.15s;
}

.fm-pagination-controls button { cursor: pointer; }
.fm-pagination-controls button:hover:not(:disabled) { border-color: var(--fm-primary); color: var(--fm-primary); background: var(--fm-primary-50); }
.fm-pagination-controls button:disabled { opacity: 0.45; cursor: not-allowed; }
.fm-pagination-controls button.fm-page-active { background: var(--fm-primary); border-color: var(--fm-primary); color: #fff; }

.fm-tabs { display: flex; align-items: center; gap: 6px; padding-bottom: 14px; border-bottom: 1px solid var(--fm-border); margin-bottom: 16px; }

.fm-tabs button {
    border: 1px solid transparent;
    border-radius: 10px;
    padding: 8px 16px;
    background: transparent;
    color: var(--fm-muted);
    font-size: 13px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.15s;
}

.fm-tabs button:hover { background: #f1f5f9; color: var(--fm-primary); }
.fm-tabs button.active { background: var(--fm-primary-50); color: var(--fm-primary-600); border-color: var(--fm-primary-100); }

.fm-status { display: inline-block; padding: 3px 10px; border-radius: 9999px; font-size: 11px; font-weight: 600; }
.fm-status.active { background: #dcfce7; color: #166534; }
.fm-status.inactive { background: #f1f5f9; color: #64748b; }

.fm-restore-btn,
.fm-perm-delete-btn {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    height: 30px;
    padding: 0 12px;
    border-radius: 8px;
    font-size: 12px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.15s;
    white-space: nowrap;
}

.fm-restore-btn { background: #ecfdf3; color: #166534; border: 1px solid #c6f0d6; }
.fm-restore-btn:hover { background: #d5f5e1; transform: translateY(-1px); }
.fm-perm-delete-btn { background: #fef2f2; color: #b91c1c; border: 1px solid #fcd0d0; }
.fm-perm-delete-btn:hover { background: #fee2e2; transform: translateY(-1px); }
.fm-recycle-actions { display: flex; align-items: center; gap: 8px; justify-content: flex-end; }

/* =========================================================
   MODALS
========================================================= */
.fm-modal-backdrop {
    position: fixed;
    inset: 0;
    z-index: 9999;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 16px;
    background: rgba(30, 41, 59, 0.32);
    backdrop-filter: blur(4px);
    animation: fm-fadein 0.2s ease;
}

@keyframes fm-fadein { from { opacity: 0; } to { opacity: 1; } }

.fm-modal {
    width: 100%;
    max-width: 480px;
    max-height: 90vh;
    overflow-y: auto;
    padding: 28px;
    border-radius: 20px;
    background: var(--fm-surface);
    box-shadow: 0 30px 70px rgba(16, 24, 40, 0.2);
    border: 1px solid var(--fm-border);
    animation: fm-modal-in 0.24s var(--fm-ease);
}

@keyframes fm-modal-in {
    from { opacity: 0; transform: translateY(14px) scale(0.97); }
    to { opacity: 1; transform: none; }
}

.fm-share-modal { max-width: 540px; }
.fm-confirm-modal { max-width: 420px; }
.fm-confirm-text { margin: 0 0 4px; font-size: 14px; line-height: 1.6; color: #475569; }
.fm-modal-hint { margin: 0 0 10px; font-size: 13px; color: var(--fm-muted); }

.fm-modal-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 20px; }
.fm-modal-header h3 { margin: 0; color: var(--fm-text-strong); font-size: 19px; font-weight: 700; letter-spacing: -0.3px; }

.fm-modal-header button,
.fm-modal-close {
    width: 32px;
    height: 32px;
    border: none;
    border-radius: 8px;
    background: #f1f5f9;
    color: var(--fm-muted);
    font-size: 18px;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    line-height: 1;
    transition: all 0.15s ease;
}

.fm-modal-header button:hover,
.fm-modal-close:hover { background: #e2e8f0; color: var(--fm-text-strong); transform: rotate(90deg); }

.fm-modal-location { font-size: 13px; color: var(--fm-muted); margin-bottom: 18px; display: flex; align-items: center; gap: 6px; }
.fm-modal-location strong { color: var(--fm-text-strong); }

.fm-form-group { position: relative; margin-bottom: 18px; }

.fm-form-group label,
.fm-modal label { display: block; margin-bottom: 8px; color: #334155; font-size: 13px; font-weight: 600; }

.fm-modal label.fm-button { display: inline-flex; margin-bottom: 0; }

.fm-optional { font-size: 12px; font-weight: normal; color: var(--fm-faint); }

.fm-modal input[type="text"],
.fm-modal input[type="datetime-local"],
.fm-modal select,
.fm-modal textarea {
    width: 100%;
    min-height: 42px;
    padding: 10px 14px;
    border: 1.5px solid var(--fm-border);
    border-radius: 10px;
    outline: none;
    background: #fff;
    color: var(--fm-text);
    font-size: 14px;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.fm-modal textarea { resize: vertical; min-height: 75px; }
.fm-modal input:hover,
.fm-modal textarea:hover { border-color: var(--fm-border-strong); }

.fm-modal input:focus,
.fm-modal select:focus,
.fm-modal textarea:focus { border-color: var(--fm-primary); box-shadow: 0 0 0 4px rgba(37, 99, 235, 0.12); }

.fm-char-count { text-align: right; font-size: 11px; color: var(--fm-faint); margin-top: 4px; }

.fm-modal-actions { display: flex; justify-content: flex-end; gap: 10px; margin-top: 24px; }

.fm-btn-secondary { background: #fff !important; border: 1.5px solid var(--fm-border) !important; color: #475569 !important; }
.fm-btn-secondary:hover { background: var(--fm-surface-2) !important; color: var(--fm-text-strong) !important; }

.fm-share-target {
    padding: 10px 14px;
    background: var(--fm-surface-2);
    border: 1px solid var(--fm-border);
    border-radius: 10px;
    font-size: 13px;
    margin-bottom: 14px;
    display: flex;
    align-items: center;
    gap: 10px;
}

/* Folder picker list */
.fm-folder-picker-list { max-height: 220px; overflow-y: auto; border: 1px solid var(--fm-border); border-radius: 10px; margin-top: 8px; background: #fff; }

.fm-folder-picker-item {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 10px 14px;
    cursor: pointer;
    border-bottom: 1px solid #f1f4f9;
    transition: background 0.12s;
}

.fm-folder-picker-item:last-child { border-bottom: none; }
.fm-folder-picker-item:hover { background: var(--fm-surface-2); }
.fm-folder-picker-item.selected { background: var(--fm-primary-50); color: var(--fm-primary-600); font-weight: 600; }
.fm-folder-picker-item i.fa-folder { font-size: 16px; }
.fm-folder-picker-name { flex: 1; font-size: 13px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.fm-folder-picker-check { color: var(--fm-primary); }

.fm-picker-new-link { margin-top: 10px; font-size: 12px; color: var(--fm-primary); cursor: pointer; display: inline-block; font-weight: 600; }
.fm-picker-new-link:hover { text-decoration: underline; }

/* Share: user & group search */
.fm-user-search {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 0 12px;
    border: 1.5px solid var(--fm-border);
    border-radius: 10px;
    background: #fff;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.fm-user-search:focus-within { border-color: var(--fm-primary); box-shadow: 0 0 0 4px rgba(37, 99, 235, 0.12); }
.fm-user-search i { color: var(--fm-faint); }
.fm-modal .fm-user-search input[type="text"] { border: none; box-shadow: none !important; padding-left: 0; }

.fm-search-help { margin: 6px 0 10px; font-size: 11px; color: var(--fm-faint); }
.fm-user-status { margin: 8px 0; font-size: 12px; color: var(--fm-muted); }
.fm-user-error { color: var(--fm-danger); }

.fm-user-results { max-height: 190px; overflow-y: auto; border: 1px solid var(--fm-border); border-radius: 10px; margin-bottom: 14px; }

.fm-user-option {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 9px 12px;
    cursor: pointer;
    border-bottom: 1px solid #f1f4f9;
    transition: background 0.12s;
}

.fm-user-option:last-child { border-bottom: none; }
.fm-user-option:hover { background: var(--fm-surface-2); }
.fm-user-option.fm-user-selected { background: var(--fm-primary-50); }

.fm-user-avatar {
    width: 32px;
    height: 32px;
    border-radius: 50%;
    background: linear-gradient(135deg, #3b82f6, #6366f1);
    color: #fff;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 12px;
    font-weight: 700;
    flex-shrink: 0;
}

.fm-user-info { flex: 1; min-width: 0; display: flex; flex-direction: column; }
.fm-user-info strong { font-size: 13px; color: var(--fm-text-strong); }
.fm-user-info span { font-size: 11px; color: var(--fm-muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.fm-date-input { margin-bottom: 4px; }

/* Image preview */
.fm-preview-backdrop { z-index: 10000; }

.fm-preview-modal {
    display: flex;
    flex-direction: column;
    width: 100%;
    max-width: 860px;
    max-height: 90vh;
    overflow: hidden;
    border-radius: 18px;
    background: #fff;
    box-shadow: 0 30px 70px rgba(16, 24, 40, 0.25);
    animation: fm-modal-in 0.24s var(--fm-ease);
}

.fm-preview-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    padding: 16px 24px;
    border-bottom: 1px solid var(--fm-border);
    color: var(--fm-text-strong);
    font-size: 15px;
    font-weight: 700;
}

.fm-preview-header button {
    width: 32px;
    height: 32px;
    border: none;
    border-radius: 8px;
    background: #f1f5f9;
    color: var(--fm-muted);
    font-size: 20px;
    cursor: pointer;
    transition: background 0.15s;
}

.fm-preview-header button:hover { background: #e2e8f0; }

.fm-preview-content {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: 280px;
    max-height: 65vh;
    padding: 24px;
    overflow: auto;
    background: #f4f7fb;
}

.fm-preview-content img { display: block; max-width: 100%; max-height: 60vh; object-fit: contain; border-radius: 8px; box-shadow: var(--fm-shadow); }

.fm-preview-nav {
    position: absolute;
    top: 50%;
    transform: translateY(-50%);
    width: 42px;
    height: 42px;
    border-radius: 50%;
    border: 1px solid var(--fm-border);
    background: rgba(255, 255, 255, 0.96);
    color: #475569;
    cursor: pointer;
    z-index: 2;
    box-shadow: var(--fm-shadow);
    transition: all 0.15s;
}

.fm-preview-nav:hover { background: var(--fm-primary); color: #fff; border-color: var(--fm-primary); }
.fm-preview-nav.fm-prev { left: 16px; }
.fm-preview-nav.fm-next { right: 16px; }

.fm-preview-footer { display: flex; justify-content: flex-end; gap: 10px; padding: 14px 24px; border-top: 1px solid var(--fm-border); }

/* Tokens */
.fm-selected-tokens { display: flex; flex-wrap: wrap; gap: 6px; margin: 8px 0; }

.fm-token {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 4px 10px;
    background: var(--fm-primary-50);
    color: var(--fm-primary-600);
    border: 1px solid var(--fm-primary-100);
    border-radius: 9999px;
    font-size: 12px;
    font-weight: 600;
    animation: fm-pop-in 0.15s var(--fm-ease);
}

.fm-token i { cursor: pointer; font-size: 12px; opacity: 0.7; transition: opacity 0.15s; }
.fm-token i:hover { opacity: 1; }

/* =========================================================
   RESPONSIVE
========================================================= */
@media (max-width: 1100px) {
    .fm-stats { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

@media (max-width: 900px) {
    .fm-sidebar { width: 200px; min-width: 200px; }
    .fm-main { padding: 20px; }
}

@media (max-width: 680px) {
    .fm-app { display: block; }
    .fm-sidebar { width: 100%; min-width: 0; min-height: auto; border-right: none; border-bottom: 1px solid var(--fm-border); }
    .fm-sidebar-bottom-art { display: none; }
    .fm-menu { display: flex; flex-wrap: wrap; gap: 6px; padding: 12px; }
    .fm-menu-label { display: none; }
    .fm-menu a { flex: 1 1 45%; margin: 0; }
    .fm-menu a.active::before { display: none; }
    .fm-main { padding: 16px; }
    .fm-stats { grid-template-columns: 1fr; }
    .fm-hero-banner { flex-direction: column; text-align: center; gap: 16px; }
    .fm-hero-graphic { justify-content: center; }
    .fm-search-pill,
    .fm-search-pill:focus-within { width: 100%; }
    .fm-header-actions { width: 100%; }
}

@media (prefers-reduced-motion: reduce) {
    .fm-app *,
    .fm-app *::before,
    .fm-app *::after { animation-duration: 0.01ms !important; transition-duration: 0.01ms !important; }
}

sp_widget.script:
(function () {
    /*
     * PUBLIC FILES widget (public_files) - Server Script
     * Only handles PUBLIC files/folders. Private data is never loaded here.
     */
    var FILE_TABLE = 'x_1830514_fm_file';
    var FOLDER_TABLE = 'x_1830514_fm_folder';
    var PUBLIC_ITEMS_TABLE = 'x_1830514_fm_public_items';
    var PUBLIC_ROLE = 'x_1830514_fm.Public';

    var userId = gs.getUserID();

    /* ---- Can this user create/edit public content? ---- */
    var hasPublicRole = false;
    if (gs.isLoggedIn()) {
        if (gs.hasRole('admin') || gs.hasRole(PUBLIC_ROLE) || gs.hasRole('x_1830514_fm.public')) {
            hasPublicRole = true;
        } else {
            var myGroups = [];
            var gm = new GlideRecord('sys_user_grmember');
            gm.addQuery('user', userId);
            gm.query();
            while (gm.next()) myGroups.push(String(gm.getValue('group')));
            if (myGroups.length > 0) {
                var roleIds = [];
                var rGr = new GlideRecord('sys_user_role');
                var rQ = rGr.addQuery('name', PUBLIC_ROLE);
                rQ.addOrCondition('name', 'x_1830514_fm.public');
                rGr.query();
                while (rGr.next()) roleIds.push(rGr.getUniqueValue());

                var gr = new GlideRecord('sys_group_has_role');
                gr.addQuery('group', 'IN', myGroups.join(','));
                if (roleIds.length > 0) {
                    gr.addQuery('role', 'IN', roleIds.join(','));
                } else {
                    gr.addQuery('role.name', 'CONTAINS', 'x_1830514_fm');
                }
                gr.setLimit(1);
                gr.query();
                if (gr.hasNext()) hasPublicRole = true;
            }
        }
    }
    data.has_public_role = !!hasPublicRole;

    /* ---- Response ---- */
    data.files = [];   // all public files
    data.folders = [];   // all public folders
    data.myFolders = [];   // my PRIVATE folders (target for "Make a copy")
    data.recycleFiles = [];   // my deleted public files
    data.recycleFolders = [];   // my deleted public folders
    data.g_ck = gs.getSession().getSessionToken();
    data.error = '';
    data.success = '';
    data.loaded = false;

    var uName = gs.getUserDisplayName() || gs.getUserName() || 'U';
    data.user_name = uName;
    var parts = uName.trim().split(/\s+/);
    data.user_initials = parts.length > 1
        ? (parts[0].charAt(0) + parts[parts.length - 1].charAt(0)).toUpperCase()
        : uName.substring(0, 2).toUpperCase();

    try {
        initPublicItemsCache();
        if (input && input.action === 'attach_to_record') { attachToRecord(); return; }
        if (input && input.action) {
            processAction();
            if (data.error || input.skip_load) return;
        }
        loadData();
    } catch (e) {
        gs.error('PublicFiles widget error: ' + e.message + '\n' + (e.stack || ''));
        data.error = e.message || 'An unexpected server error occurred. Please refresh and try again.';
    }

    /* ==================================================
       DISPATCHER
    ================================================== */
    function processAction() {
        switch (input.action) {
            case 'refresh': break;
            case 'create_folder': createFolder(); break;
            case 'rename_folder': renameFolder(); break;
            case 'delete_folder': deleteFolder(); break;
            case 'restore_folder': restoreFolder(); break;
            case 'delete_folder_permanent': deleteFolderPermanent(); break;
            case 'create_file': createFile(); break;
            case 'sync_public_attachment': syncPublicAttachment(); break;
            case 'discard_file': discardFile(); break;
            case 'update_file': updateFile(); break;
            case 'rename_file': renameFile(); break;
            case 'delete_file': deleteFile(); break;
            case 'restore_file': restoreFile(); break;
            case 'delete_file_permanent': deleteFilePermanent(); break;
            case 'empty_bin': emptyBin(); break;
            case 'copy_to_my_folder': copyToMyFolder(); break;
            default: data.error = 'Invalid action: ' + (input.action || '');
        }
    }

    /* ==================================================
       HELPERS
    ================================================== */
    function getRecord(table, sysId) {
        if (!sysId) return null;
        try { var g = new GlideRecord(table); if (g.get(sysId)) return g; } catch (e) { }
        return null;
    }
    function isDeleted(g) { var v = String(g.getValue('is_deleted')); return v === '1' || v === 'true'; }
    function _setIf(g, f, v) { if (g.isValidField(f)) g.setValue(f, v); }

    /* ---- Nickname helpers (uses the "nickname" column if it exists, otherwise a [nick:...] marker in description) ---- */
    function cleanNick(s) { return String(s || '').replace(/[\[\]]/g, '').trim().substring(0, 50); }
    function cleanDescText(d) {
        return String(d || '').replace(/\[nick:[^\]]*\]\s*/ig, '').replace(/\[public\]\s*/ig, '').trim();
    }
    function readNick(gr) {
        if (gr.isValidField('nickname')) return gr.getValue('nickname') || '';
        var m = (gr.getValue('description') || '').match(/\[nick:([^\]]*)\]/i);
        return m ? m[1] : '';
    }
    function writeNick(gr, nick) {
        nick = cleanNick(nick);
        if (gr.isValidField('nickname')) { gr.setValue('nickname', nick); return; }
        var d = (gr.getValue('description') || '').replace(/\[nick:[^\]]*\]\s*/ig, '').trim();
        gr.setValue('description', (d ? d + ' ' : '') + (nick ? '[nick:' + nick + ']' : ''));
    }

    var _publicFileIds = {};
    var _publicFolderIds = {};
    var _publicCacheLoaded = false;

    function initPublicItemsCache(force) {
        if (_publicCacheLoaded && !force) return;
        _publicFileIds = {};
        _publicFolderIds = {};
        try {
            var pi = new GlideRecord(PUBLIC_ITEMS_TABLE);
            pi.addQuery('active', true);
            pi.query();
            while (pi.next()) {
                var fId = String(pi.getValue('file') || '');
                var foldId = String(pi.getValue('folder') || '');
                var st = String(pi.getValue('source_type') || '').toLowerCase();
                var pSysId = pi.getUniqueValue();
                if (fId) _publicFileIds[fId] = pSysId;
                if (foldId && (st === 'folder' || !fId)) _publicFolderIds[foldId] = pSysId;
            }
            _publicCacheLoaded = true;
        } catch (e) {
            gs.error('PublicFiles error reading ' + PUBLIC_ITEMS_TABLE + ': ' + e.message);
        }
    }

    function isRecordPublic(g) {
        if (!g) return false;
        initPublicItemsCache();
        var id = g.getUniqueValue();
        if (_publicFileIds[id] || _publicFolderIds[id]) return true;

        if (g.isValidField('is_public')) {
            var v = g.getValue('is_public');
            if (v === true || v === 'true' || v === '1' || v === 1) return true;
        }
        if (g.isValidField('access') && (g.getValue('access') || '').toLowerCase() === 'public') return true;
        var desc = g.isValidField('description') ? (g.getValue('description') || '') : '';
        return desc.indexOf('[public]') !== -1;
    }

    function copyAttachmentToPublicItem(fileSysId, publicItemSysId) {
        if (!fileSysId) return;
        try {
            if (!publicItemSysId || typeof publicItemSysId !== 'string') {
                publicItemSysId = _publicFileIds[fileSysId];
            }
            if (!publicItemSysId || typeof publicItemSysId !== 'string') {
                var pi = new GlideRecord(PUBLIC_ITEMS_TABLE);
                pi.addQuery('file', fileSysId);
                pi.query();
                if (pi.next()) publicItemSysId = pi.getUniqueValue();
            }
            if (!publicItemSysId) return;

            // Check if source file has an attachment
            var srcAtt = new GlideRecord('sys_attachment');
            srcAtt.addQuery('table_name', FILE_TABLE);
            srcAtt.addQuery('table_sys_id', fileSysId);
            srcAtt.query();
            if (!srcAtt.hasNext()) return;

            // Check if target public item already has an attachment
            var tgtAtt = new GlideRecord('sys_attachment');
            tgtAtt.addQuery('table_name', PUBLIC_ITEMS_TABLE);
            tgtAtt.addQuery('table_sys_id', publicItemSysId);
            tgtAtt.query();
            if (!tgtAtt.hasNext()) {
                var gsa = new GlideSysAttachment();
                gsa.copy(FILE_TABLE, fileSysId, PUBLIC_ITEMS_TABLE, publicItemSysId);
            }
        } catch (e) {
            gs.error('PublicFiles copyAttachmentToPublicItem error: ' + e.message);
        }
    }

    function syncPublicAttachment() {
        var fileId = (input.file_sys_id || '').trim();
        var pubItemId = (input.public_item_sys_id || '').trim();
        if (!fileId) { data.error = 'File sys_id is required.'; return; }
        copyAttachmentToPublicItem(fileId, pubItemId);
        data.success = 'Attachment synced to public item.';
    }

    function publishFileRecord(fileId, title, folderId, nickname) {
        if (!fileId) return null;
        try {
            var gr = new GlideRecord(PUBLIC_ITEMS_TABLE);
            gr.addQuery('file', fileId);
            gr.query();
            var desc = nickname ? ('[nick:' + nickname + '] ' + title) : title;
            var nowGdt = (typeof gs !== 'undefined' && gs.nowDateTime) ? gs.nowDateTime() : (new GlideDateTime()).getValue();
            var pubUser = String(userId || (typeof gs !== 'undefined' ? gs.getUserID() : ''));
            var pubId = null;
            if (gr.next()) {
                _setIf(gr, 'public_title', title);
                _setIf(gr, 'source_type', 'File');
                _setIf(gr, 'active', true);
                if (folderId) _setIf(gr, 'folder', folderId);
                _setIf(gr, 'description', desc);
                _setIf(gr, 'published_by', pubUser);
                _setIf(gr, 'published_on', nowGdt);
                gr.update();
                pubId = gr.getUniqueValue();
            } else {
                gr.initialize();
                _setIf(gr, 'public_title', title);
                _setIf(gr, 'source_type', 'File');
                _setIf(gr, 'active', true);
                _setIf(gr, 'file', fileId);
                if (folderId) _setIf(gr, 'folder', folderId);
                _setIf(gr, 'description', desc);
                _setIf(gr, 'published_by', pubUser);
                _setIf(gr, 'published_on', nowGdt);
                pubId = gr.insert();
            }
            if (pubId) {
                _publicFileIds[fileId] = pubId;
                copyAttachmentToPublicItem(fileId, pubId);
            }
            return pubId;
        } catch (e) {
            gs.error('PublicFiles publishFileRecord error: ' + e.message);
            return null;
        }
    }

    function publishFolderRecord(folderId, title, description) {
        if (!folderId) return null;
        try {
            var gr = new GlideRecord(PUBLIC_ITEMS_TABLE);
            gr.addQuery('folder', folderId);
            gr.addQuery('source_type', 'Folder');
            gr.query();
            var nowGdt = (typeof gs !== 'undefined' && gs.nowDateTime) ? gs.nowDateTime() : (new GlideDateTime()).getValue();
            var pubUser = String(userId || (typeof gs !== 'undefined' ? gs.getUserID() : ''));
            var pubId = null;
            if (gr.next()) {
                _setIf(gr, 'public_title', title);
                _setIf(gr, 'source_type', 'Folder');
                _setIf(gr, 'active', true);
                if (description) _setIf(gr, 'description', description);
                _setIf(gr, 'published_by', pubUser);
                _setIf(gr, 'published_on', nowGdt);
                gr.update();
                pubId = gr.getUniqueValue();
            } else {
                gr.initialize();
                _setIf(gr, 'public_title', title);
                _setIf(gr, 'source_type', 'Folder');
                _setIf(gr, 'active', true);
                _setIf(gr, 'folder', folderId);
                if (description) _setIf(gr, 'description', description);
                _setIf(gr, 'published_by', pubUser);
                _setIf(gr, 'published_on', nowGdt);
                pubId = gr.insert();
            }
            if (pubId) {
                _publicFolderIds[folderId] = pubId;
            }
            return pubId;
        } catch (e) {
            gs.error('PublicFiles publishFolderRecord error: ' + e.message);
            return null;
        }
    }

    function unpublishFile(fileId) {
        if (!fileId) return;
        delete _publicFileIds[fileId];
        try {
            var gr = new GlideRecord(PUBLIC_ITEMS_TABLE);
            gr.addQuery('file', fileId);
            gr.query();
            while (gr.next()) {
                if (gr.isValidField('active')) {
                    gr.setValue('active', false);
                    gr.update();
                } else {
                    gr.deleteRecord();
                }
            }
        } catch (e) { }
    }

    function unpublishFolder(folderId) {
        if (!folderId) return;
        delete _publicFolderIds[folderId];
        try {
            var gr = new GlideRecord(PUBLIC_ITEMS_TABLE);
            gr.addQuery('folder', folderId);
            gr.addQuery('source_type', 'Folder');
            gr.query();
            while (gr.next()) {
                if (gr.isValidField('active')) {
                    gr.setValue('active', false);
                    gr.update();
                } else {
                    gr.deleteRecord();
                }
            }
        } catch (e) { }
    }

    function restorePublicFileItem(fileId) {
        if (!fileId) return;
        _publicFileIds[fileId] = true;
        try {
            var gr = new GlideRecord(PUBLIC_ITEMS_TABLE);
            gr.addQuery('file', fileId);
            gr.query();
            while (gr.next()) {
                if (gr.isValidField('active')) {
                    gr.setValue('active', true);
                    gr.update();
                }
            }
        } catch (e) { }
    }

    function restorePublicFolderItem(folderId) {
        if (!folderId) return;
        _publicFolderIds[folderId] = true;
        try {
            var gr = new GlideRecord(PUBLIC_ITEMS_TABLE);
            gr.addQuery('folder', folderId);
            gr.addQuery('source_type', 'Folder');
            gr.query();
            while (gr.next()) {
                if (gr.isValidField('active')) {
                    gr.setValue('active', true);
                    gr.update();
                }
            }
        } catch (e) { }
    }

    function renamePublicItem(targetType, targetId, newTitle) {
        if (!targetId || !newTitle) return;
        try {
            var gr = new GlideRecord(PUBLIC_ITEMS_TABLE);
            if (targetType === 'file') gr.addQuery('file', targetId);
            else {
                gr.addQuery('folder', targetId);
                gr.addQuery('source_type', 'Folder');
            }
            gr.query();
            while (gr.next()) {
                if (gr.isValidField('public_title')) {
                    gr.setValue('public_title', newTitle);
                    gr.update();
                }
            }
        } catch (e) { }
    }

    function deletePublicItemPermanently(targetType, targetId) {
        if (!targetId) return;
        if (targetType === 'file') delete _publicFileIds[targetId];
        else delete _publicFolderIds[targetId];
        try {
            var gr = new GlideRecord(PUBLIC_ITEMS_TABLE);
            if (targetType === 'file') gr.addQuery('file', targetId);
            else {
                gr.addQuery('folder', targetId);
                gr.addQuery('source_type', 'Folder');
            }
            gr.query();
            while (gr.next()) gr.deleteRecord();
        } catch (e) { }
    }

    /** Owner / Editor (public-role holders) / Viewer (everybody else). '' = not a public record */
    function permOf(g) {
        if (!g || isDeleted(g) || !isRecordPublic(g)) return '';
        if (!hasPublicRole) return 'Viewer';
        if (g.getValue('owner') === userId) return 'Owner';
        return 'Editor';
    }
    function canEdit(p) { return p === 'Owner' || p === 'Editor'; }
    function isOwner(g) { return !!g && hasPublicRole && g.getValue('owner') === userId; }
    function needRole() {
        if (hasPublicRole) return false;
        data.error = 'You need the role ' + PUBLIC_ROLE + ' to do this.';
        return true;
    }

    function getAttachmentId(fileId) {
        var att = new GlideRecord('sys_attachment');
        att.addQuery('table_name', FILE_TABLE);
        att.addQuery('table_sys_id', fileId);
        att.orderByDesc('sys_created_on');
        att.setLimit(1);
        att.query();
        return att.next() ? att.getUniqueValue() : '';
    }

    function fillAttachmentIds(list) {
        var ids = list.map(function (f) { return f.sys_id; });
        var map = {};
        if (ids.length) {
            var att = new GlideRecord('sys_attachment');
            att.addQuery('table_name', FILE_TABLE);
            att.addQuery('table_sys_id', 'IN', ids.join(','));
            att.orderBy('sys_created_on');
            att.query();
            while (att.next()) map[att.getValue('table_sys_id')] = att.getUniqueValue();
        }
        list.forEach(function (f) { f.attachment_id = map[f.sys_id] || ''; });
    }

    function addFileToList(file) {
        var permission = permOf(file);
        if (!permission) return null;
        var fn = file.getValue('filename') || file.getValue('file_name') || file.getValue('name') || file.getDisplayValue() || '';
        data.files.push({
            sys_id: file.getUniqueValue(),
            filename: fn,
            folder: file.getValue('folder') || '',
            folder_name: file.getDisplayValue('folder') || '',
            description: cleanDescText(file.getValue('description')),
            nickname: readNick(file),
            owner: file.getValue('owner') || '',
            owner_name: file.getDisplayValue('owner') || '',
            file_extension: file.getValue('file_extension') || '',
            file_size: parseInt(file.getValue('file_size'), 10) || 0,
            content_type: file.getValue('content_type') || '',
            attachment_id: '',
            permission: permission,
            can_edit: canEdit(permission),
            sys_created_on: file.getValue('sys_created_on') || '',
            created_date: file.getDisplayValue('sys_created_on') || ''
        });
    }

    function folderColor(folder) {
        var color = '';
        if (folder.isValidField('color')) color = folder.getValue('color') || '';
        if (!color && folder.isValidField('folder_color')) color = folder.getValue('folder_color') || '';
        if (!color) {
            var m = (folder.getValue('description') || '').match(/\[color:([a-z0-9#-]+)\]/i);
            if (m) color = m[1];
        }
        return color || 'orange';
    }

    function addFolderToList(folder, target, permission) {
        var fn = folder.getValue('folder_name') || folder.getValue('name') || folder.getDisplayValue() || '';
        var desc = (folder.getValue('description') || '')
            .replace(/\[color:[a-z0-9#-]+\]\s*/ig, '').replace(/\[public\]\s*/ig, '').trim();
        target.push({
            sys_id: folder.getUniqueValue(),
            folder_name: fn,
            parent_folder: folder.getValue('parent_folder') || '',
            description: desc,
            color: folderColor(folder),
            owner: folder.getValue('owner') || '',
            sys_created_on: folder.getValue('sys_created_on') || '',
            created_date: folder.getDisplayValue('sys_created_on') || '',
            permission: permission,
            can_edit: canEdit(permission)
        });
    }

    /** Is there already a PUBLIC folder with this name in the same parent? */
    function _findFolderId(name, parentId, excludeId) {
        var g = new GlideRecord(FOLDER_TABLE);
        g.addQuery('is_deleted', false);
        var c = g.addQuery('folder_name', name);
        c.addOrCondition('name', name);
        if (parentId) g.addQuery('parent_folder', parentId); else g.addNullQuery('parent_folder');
        if (excludeId) g.addQuery('sys_id', '!=', excludeId);
        g.query();
        while (g.next()) if (isRecordPublic(g)) return g.getUniqueValue();
        return '';
    }

    function _deleteAttachments(fileId) {
        var att = new GlideRecord('sys_attachment');
        att.addQuery('table_name', FILE_TABLE);
        att.addQuery('table_sys_id', fileId);
        att.query();
        att.deleteMultiple();
    }

    /* ==================================================
       ATTACH TO RECORD (picker mode)
    ================================================== */
    function attachToRecord() {
        data.attached_count = 0;
        var ids = input.file_ids || [];
        var targetTable = (input.target_table || '').trim();
        var targetId = (input.target_sys_id || '').trim();
        if (!ids.length || !targetTable || !targetId) { data.error = 'Missing file or target record details.'; return; }

        var secure = new GlideRecordSecure(targetTable);
        if (!secure.isValid()) { data.error = 'Invalid target table.'; return; }
        if (!secure.get(targetId)) { data.error = 'Target record not found. Save the record first.'; return; }
        if (!secure.canWrite()) { data.error = 'You do not have permission to attach files to this record.'; return; }

        var target = new GlideRecord(targetTable);
        target.get(targetId);
        var gsa = new GlideSysAttachment(), failed = [];

        for (var i = 0; i < ids.length; i++) {
            var file = getRecord(FILE_TABLE, ids[i]);
            if (!file || !permOf(file)) { failed.push('a file you cannot access'); continue; }
            var attId = getAttachmentId(file.getUniqueValue());
            var att = attId ? getRecord('sys_attachment', attId) : null;
            if (!att) { failed.push(file.getValue('filename') || 'a file'); continue; }
            var newId = gsa.writeContentStream(target, att.getValue('file_name'), att.getValue('content_type'), gsa.getContentStream(attId));
            if (newId) data.attached_count++; else failed.push(att.getValue('file_name'));
        }
        if (failed.length) data.error = 'Could not attach: ' + failed.join(', ');
        else data.success = data.attached_count + ' file(s) attached.';
    }

    /* ==================================================
       FOLDERS
    ================================================== */
    function createFolder() {
        if (needRole()) return;
        var name = (input.folder_name || '').trim();
        var parentId = (input.parent_folder || '').trim();
        var description = (input.description || '').trim();

        if (!name) { data.error = 'Please enter a folder name.'; return; }
        if (name.length > 40) { data.error = 'Folder name cannot exceed 40 characters.'; return; }

        if (parentId) {
            var parent = getRecord(FOLDER_TABLE, parentId);
            if (!parent || isDeleted(parent) || !isRecordPublic(parent)) { data.error = 'Parent public folder not found.'; return; }
        }

        var existing = _findFolderId(name, parentId, null);
        if (existing) {
            if (input.reuse_existing) { data.folder_sys_id = existing; data.success = 'Using existing folder "' + name + '".'; return; }
            data.error = 'A public folder with this name already exists in this location.';
            return;
        }

        var color = (input.color || 'orange').trim().toLowerCase();
        var folder = new GlideRecord(FOLDER_TABLE);
        folder.initialize();
        if (folder.isValidField('folder_name')) folder.setValue('folder_name', name); else folder.setValue('name', name);
        _setIf(folder, 'color', color);
        _setIf(folder, 'folder_color', color);
        _setIf(folder, 'is_public', true);
        _setIf(folder, 'access', 'public');

        var stored = description;
        if (!folder.isValidField('color') && !folder.isValidField('folder_color')) stored = (stored ? stored + ' ' : '') + '[color:' + color + ']';
        stored = (stored ? stored + ' ' : '') + '[public]';

        folder.setValue('owner', userId);
        folder.setValue('description', stored);
        folder.setValue('is_deleted', false);
        _setIf(folder, 'active', true);
        if (parentId) folder.setValue('parent_folder', parentId);

        var id = folder.insert();
        if (!id) { data.error = 'Unable to create folder. Please check your permissions.'; return; }
        var pubFolderId = publishFolderRecord(id, name, description);
        data.folder_sys_id = id;
        data.public_item_sys_id = pubFolderId || '';
        data.success = 'Folder "' + name + '" created successfully.';
    }

    function renameFolder() {
        if (needRole()) return;
        var name = (input.folder_name || '').trim();
        var folder = getRecord(FOLDER_TABLE, (input.sys_id || '').trim());
        if (!name || !folder) { data.error = 'Folder ID and new name are required.'; return; }
        if (name.length > 40) { data.error = 'Folder name cannot exceed 40 characters.'; return; }
        if (isDeleted(folder) || !isRecordPublic(folder)) { data.error = 'Folder not found.'; return; }
        if (!isOwner(folder)) { data.error = 'Only the folder owner can rename this folder.'; return; }
        if (_findFolderId(name, folder.getValue('parent_folder') || '', folder.getUniqueValue())) {
            data.error = 'A public folder with this name already exists in this location.'; return;
        }
        folder.setValue('folder_name', name);
        var color = (input.color || '').trim().toLowerCase();
        if (color) {
            _setIf(folder, 'color', color);
            _setIf(folder, 'folder_color', color);
            if (!folder.isValidField('color') && !folder.isValidField('folder_color')) {
                var d = (folder.getValue('description') || '').replace(/\[color:[a-z0-9#-]+\]\s*/ig, '').trim();
                folder.setValue('description', (d ? d + ' ' : '') + '[color:' + color + ']');
            }
        }
        if (!folder.update()) { data.error = 'Unable to rename folder.'; return; }
        renamePublicItem('folder', folder.getUniqueValue(), name);
        data.success = 'Folder renamed to "' + name + '".';
    }

    function deleteFolder() {
        if (needRole()) return;
        var folder = getRecord(FOLDER_TABLE, input.sys_id);
        if (!folder || isDeleted(folder) || !isRecordPublic(folder) || !isOwner(folder)) {
            data.error = 'Only the folder owner can delete this folder.'; return;
        }
        var id = folder.getUniqueValue();

        var sub = new GlideRecord(FOLDER_TABLE);
        sub.addQuery('parent_folder', id); sub.addQuery('is_deleted', false); sub.setLimit(1); sub.query();
        if (sub.hasNext()) { data.error = 'Please delete or move all subfolders first.'; return; }

        var files = new GlideRecord(FILE_TABLE);
        files.addQuery('folder', id); files.addQuery('is_deleted', false); files.setLimit(1); files.query();
        if (files.hasNext()) { data.error = 'Please delete or move all files in this folder first.'; return; }

        folder.setValue('is_deleted', true);
        _setIf(folder, 'deleted_by', userId);
        _setIf(folder, 'deleted_date', new GlideDateTime());
        _setIf(folder, 'active', false);
        folder.update();
        unpublishFolder(id);
        data.success = 'Folder moved to Recycle Bin.';
    }

    function restoreFolder() {
        if (needRole()) return;
        var folder = getRecord(FOLDER_TABLE, input.sys_id);
        if (!folder || !isOwner(folder) || !isDeleted(folder) || !isRecordPublic(folder)) { data.error = 'You cannot restore this folder.'; return; }
        var parentId = folder.getValue('parent_folder');
        if (parentId) {
            var p = getRecord(FOLDER_TABLE, parentId);
            if (!p || isDeleted(p)) { data.error = 'Please restore the parent folder first.'; return; }
        }
        if (_findFolderId(folder.getValue('folder_name'), parentId || '', folder.getUniqueValue())) {
            data.error = 'A public folder with this name already exists in that location.'; return;
        }
        folder.setValue('is_deleted', false);
        _setIf(folder, 'deleted_by', ''); _setIf(folder, 'deleted_date', ''); _setIf(folder, 'active', true);
        folder.update();
        restorePublicFolderItem(folder.getUniqueValue());
        data.success = 'Folder restored successfully.';
    }

    function deleteFolderPermanent() {
        if (needRole()) return;
        var folder = getRecord(FOLDER_TABLE, input.sys_id);
        if (!folder || !isOwner(folder) || !isDeleted(folder) || !isRecordPublic(folder)) { data.error = 'You cannot permanently delete this folder.'; return; }
        var id = folder.getUniqueValue();

        var sub = new GlideRecord(FOLDER_TABLE);
        sub.addQuery('parent_folder', id); sub.setLimit(1); sub.query();
        if (sub.hasNext()) { data.error = 'Subfolders still exist (check the Recycle Bin and delete them first).'; return; }
        var files = new GlideRecord(FILE_TABLE);
        files.addQuery('folder', id); files.setLimit(1); files.query();
        if (files.hasNext()) { data.error = 'Files still exist (check the Recycle Bin and delete them first).'; return; }

        deletePublicItemPermanently('folder', id);
        folder.deleteRecord();
        data.success = 'Folder permanently deleted.';
    }

    /* ==================================================
       FILES
    ================================================== */
    function createFile() {
        if (needRole()) return;
        var filename = (input.filename || '').trim();
        var folderId = (input.folder || '').trim();
        if (!filename) { data.error = 'File name is required.'; return; }
        if (filename.length > 255) { data.error = 'File name is too long (max 255 characters).'; return; }

        if (folderId) {
            var folder = getRecord(FOLDER_TABLE, folderId);
            if (!folder || isDeleted(folder) || !isRecordPublic(folder)) { folderId = ''; }
        }

        var file = new GlideRecord(FILE_TABLE);
        file.initialize();
        if (file.isValidField('filename')) file.setValue('filename', filename);
        if (file.isValidField('file_name')) file.setValue('file_name', filename);
        if (file.isValidField('name')) file.setValue('name', filename);
        if (file.isValidField('file')) file.setValue('file', filename);
        if (file.isValidField('short_description')) file.setValue('short_description', filename);

        if (folderId) {
            if (file.isValidField('folder')) file.setValue('folder', folderId);
            if (file.isValidField('parent_folder')) file.setValue('parent_folder', folderId);
            if (file.isValidField('parent')) file.setValue('parent', folderId);
        }

        _setIf(file, 'owner', userId);
        _setIf(file, 'file_extension', (input.extension || '').toLowerCase());
        _setIf(file, 'file_size', parseInt(input.file_size, 10) || 0);
        _setIf(file, 'content_type', input.content_type || 'application/octet-stream');
        _setIf(file, 'is_deleted', false);
        _setIf(file, 'description', '[public]');
        _setIf(file, 'current_version', 1);
        _setIf(file, 'is_public', true);
        _setIf(file, 'access', 'public');
        writeNick(file, input.nickname);

        var id = file.insert();
        if (!id && !folderId) {
            // If insert failed at root, destination folder may be a mandatory dictionary reference
            var pubFolder = new GlideRecord(FOLDER_TABLE);
            pubFolder.addQuery('is_deleted', false);
            pubFolder.query();
            while (pubFolder.next()) {
                if (isRecordPublic(pubFolder)) {
                    folderId = pubFolder.getUniqueValue();
                    break;
                }
            }
            if (!folderId) {
                pubFolder.initialize();
                if (pubFolder.isValidField('folder_name')) pubFolder.setValue('folder_name', 'General');
                else if (pubFolder.isValidField('name')) pubFolder.setValue('name', 'General');
                _setIf(pubFolder, 'owner', userId);
                _setIf(pubFolder, 'is_deleted', false);
                _setIf(pubFolder, 'is_public', true);
                _setIf(pubFolder, 'access', 'public');
                _setIf(pubFolder, 'description', '[public]');
                _setIf(pubFolder, 'color', 'blue');
                folderId = pubFolder.insert();
                if (folderId) publishFolderRecord(folderId, 'General', '[public]');
            }
            if (folderId) {
                var retry = new GlideRecord(FILE_TABLE);
                retry.initialize();
                if (retry.isValidField('filename')) retry.setValue('filename', filename);
                if (retry.isValidField('file_name')) retry.setValue('file_name', filename);
                if (retry.isValidField('name')) retry.setValue('name', filename);
                if (retry.isValidField('file')) retry.setValue('file', filename);
                if (retry.isValidField('short_description')) retry.setValue('short_description', filename);
                if (retry.isValidField('folder')) retry.setValue('folder', folderId);
                if (retry.isValidField('parent_folder')) retry.setValue('parent_folder', folderId);
                if (retry.isValidField('parent')) retry.setValue('parent', folderId);
                _setIf(retry, 'owner', userId);
                _setIf(retry, 'file_extension', (input.extension || '').toLowerCase());
                _setIf(retry, 'file_size', parseInt(input.file_size, 10) || 0);
                _setIf(retry, 'content_type', input.content_type || 'application/octet-stream');
                _setIf(retry, 'is_deleted', false);
                _setIf(retry, 'description', '[public]');
                _setIf(retry, 'current_version', 1);
                _setIf(retry, 'is_public', true);
                _setIf(retry, 'access', 'public');
                writeNick(retry, input.nickname);
                id = retry.insert();
            }
        }

        if (!id) { data.error = 'Unable to create file record. Please check your permissions.'; return; }
        var pubItemId = publishFileRecord(id, filename, folderId, input.nickname);
        data.file_sys_id = id;
        data.public_item_sys_id = pubItemId || '';
        data.g_ck = gs.getSession().getSessionToken();
        data.success = 'File record created.';
    }

    function discardFile() {
        var file = getRecord(FILE_TABLE, input.sys_id);
        if (!file || !isOwner(file)) return;
        if (getAttachmentId(file.getUniqueValue())) return;
        deletePublicItemPermanently('file', file.getUniqueValue());
        file.deleteRecord();
    }

    function updateFile() {
        if (needRole()) return;
        var file = getRecord(FILE_TABLE, input.sys_id);
        if (!file || !canEdit(permOf(file))) { data.error = 'You do not have permission to edit this file.'; return; }
        var keepNick = readNick(file);
        var desc = cleanDescText(input.description).substring(0, 900);
        file.setValue('description', (desc ? desc + ' ' : '') + '[public]');
        writeNick(file, input.nickname !== undefined ? input.nickname : keepNick);
        if (!file.update()) { data.error = 'Unable to update file.'; return; }
        publishFileRecord(file.getUniqueValue(), file.getValue('filename') || file.getValue('name'), file.getValue('folder') || '', input.nickname !== undefined ? input.nickname : keepNick);
        data.success = 'File updated successfully.';
    }

    function renameFile() {
        if (needRole()) return;
        var newName = (input.filename || '').trim();
        var file = getRecord(FILE_TABLE, input.sys_id);
        if (!newName) { data.error = 'Please enter a file name.'; return; }
        if (newName.length > 255) { data.error = 'File name is too long (max 255 characters).'; return; }
        if (/[\\\/]/.test(newName)) { data.error = 'File name cannot contain slashes.'; return; }
        if (!file || isDeleted(file) || !isRecordPublic(file)) { data.error = 'File not found.'; return; }
        if (!isOwner(file)) { data.error = 'Only the file owner can rename this file.'; return; }

        if (file.isValidField('filename')) file.setValue('filename', newName);
        else if (file.isValidField('file_name')) file.setValue('file_name', newName);
        else file.setValue('name', newName);
        _setIf(file, 'file_extension', newName.indexOf('.') !== -1 ? newName.split('.').pop().toLowerCase() : '');
        if (!file.update()) { data.error = 'Unable to rename file.'; return; }

        try {
            var attId = getAttachmentId(file.getUniqueValue());
            var att = attId ? getRecord('sys_attachment', attId) : null;
            if (att) { att.setValue('file_name', newName); att.update(); }
        } catch (e) { gs.warn('PublicFiles rename: attachment name not updated: ' + e.message); }
        renamePublicItem('file', file.getUniqueValue(), newName);
        data.success = 'File renamed to "' + newName + '".';
    }

    function deleteFile() {
        if (needRole()) return;
        var file = getRecord(FILE_TABLE, input.sys_id);
        if (!file || isDeleted(file) || !isRecordPublic(file) || !isOwner(file)) { data.error = 'Only the file owner can delete this file.'; return; }
        _setIf(file, 'original_folder', file.getValue('folder'));
        file.setValue('is_deleted', true);
        _setIf(file, 'deleted_by', userId);
        _setIf(file, 'deleted_date', new GlideDateTime());
        file.update();
        unpublishFile(file.getUniqueValue());
        data.success = 'File moved to Recycle Bin.';
    }

    function restoreFile() {
        if (needRole()) return;
        var file = getRecord(FILE_TABLE, input.sys_id);
        if (!file || !isOwner(file) || !isDeleted(file) || !isRecordPublic(file)) { data.error = 'You cannot restore this file.'; return; }
        var orig = file.isValidField('original_folder') ? file.getValue('original_folder') : '';
        if (orig) {
            var f = getRecord(FOLDER_TABLE, orig);
            if (!f || isDeleted(f)) { data.error = 'The original folder no longer exists. Please restore it first.'; return; }
            file.setValue('folder', orig);
        }
        file.setValue('is_deleted', false);
        _setIf(file, 'deleted_by', ''); _setIf(file, 'deleted_date', ''); _setIf(file, 'original_folder', '');
        file.update();
        restorePublicFileItem(file.getUniqueValue());
        data.success = 'File restored successfully.';
    }

    function deleteFilePermanent() {
        if (needRole()) return;
        var file = getRecord(FILE_TABLE, input.sys_id);
        if (!file || !isOwner(file) || !isDeleted(file) || !isRecordPublic(file)) { data.error = 'You cannot permanently delete this file.'; return; }
        deletePublicItemPermanently('file', file.getUniqueValue());
        _deleteAttachments(file.getUniqueValue());
        file.deleteRecord();
        data.success = 'File permanently deleted.';
    }

    function emptyBin() {
        if (needRole()) return;
        var files = new GlideRecord(FILE_TABLE);
        files.addQuery('owner', userId); files.addQuery('is_deleted', true); files.query();
        while (files.next()) {
            if (!isRecordPublic(files)) continue;
            deletePublicItemPermanently('file', files.getUniqueValue());
            _deleteAttachments(files.getUniqueValue());
            files.deleteRecord();
        }
        var folders = new GlideRecord(FOLDER_TABLE);
        folders.addQuery('owner', userId); folders.addQuery('is_deleted', true); folders.query();
        while (folders.next()) {
            if (isRecordPublic(folders)) {
                deletePublicItemPermanently('folder', folders.getUniqueValue());
                folders.deleteRecord();
            }
        }
        data.success = 'Recycle Bin emptied.';
    }

    /* ==================================================
       COPY A PUBLIC FILE INTO MY PRIVATE FOLDER
    ================================================== */
    function copyToMyFolder() {
        var src = getRecord(FILE_TABLE, input.sys_id);
        var target = getRecord(FOLDER_TABLE, input.folder_id);

        if (!src || !permOf(src)) { data.error = 'Public file not found.'; return; }
        if (!target || isDeleted(target) || !isOwner(target) || isRecordPublic(target)) {
            data.error = 'Please choose one of your own private folders.'; return;
        }

        var nf = new GlideRecord(FILE_TABLE);
        nf.initialize();
        var fn = src.getValue('filename') || src.getValue('file_name') || src.getValue('name') || '';
        if (nf.isValidField('filename')) nf.setValue('filename', fn);
        else if (nf.isValidField('file_name')) nf.setValue('file_name', fn);
        else nf.setValue('name', fn);

        nf.setValue('folder', target.getUniqueValue());
        nf.setValue('owner', userId);
        nf.setValue('description', cleanDescText(src.getValue('description')));
        _setIf(nf, 'file_extension', src.getValue('file_extension') || '');
        _setIf(nf, 'file_size', src.getValue('file_size') || 0);
        _setIf(nf, 'content_type', src.getValue('content_type') || '');
        _setIf(nf, 'current_version', 1);
        _setIf(nf, 'is_deleted', false);
        writeNick(nf, readNick(src));
        var newId = nf.insert();
        if (!newId) { data.error = 'Unable to copy the file.'; return; }

        if (getAttachmentId(src.getUniqueValue())) {
            try {
                new GlideSysAttachment().copy(FILE_TABLE, src.getUniqueValue(), FILE_TABLE, newId);
            } catch (e) {
                gs.error('PublicFiles: attachment copy failed: ' + e.message);
                var bad = getRecord(FILE_TABLE, newId);
                if (bad) bad.deleteRecord();
                data.error = 'Unable to copy the file content.';
                return;
            }
        }
        data.success = 'File copied to your private folder "' + target.getValue('folder_name') + '".';
    }

    /* ==================================================
       LOAD DATA
    ================================================== */
    function loadData() {
        initPublicItemsCache();

        var folders = new GlideRecord(FOLDER_TABLE);
        folders.addQuery('is_deleted', false);
        folders.orderBy('folder_name');
        folders.query();
        while (folders.next()) {
            if (isRecordPublic(folders)) {
                var p = permOf(folders);
                if (p) {
                    addFolderToList(folders, data.folders, p);
                    var foldId = folders.getUniqueValue();
                    var pubFoldId = _publicFolderIds[foldId];
                    if (!pubFoldId || typeof pubFoldId !== 'string') {
                        var foldName = folders.getValue('folder_name') || folders.getValue('name') || '';
                        publishFolderRecord(foldId, foldName, folders.getValue('description') || '');
                    }
                }
            }
        }

        var files = new GlideRecord(FILE_TABLE);
        files.addQuery('is_deleted', false);
        files.orderByDesc('sys_created_on');
        files.query();
        while (files.next()) {
            if (isRecordPublic(files)) {
                addFileToList(files);
                var fId = files.getUniqueValue();
                var pubItemId = _publicFileIds[fId];
                if (!pubItemId || typeof pubItemId !== 'string') {
                    var fn = files.getValue('filename') || files.getValue('file_name') || files.getValue('name') || '';
                    pubItemId = publishFileRecord(fId, fn, files.getValue('folder') || '', readNick(files));
                }
                if (pubItemId) {
                    copyAttachmentToPublicItem(fId, pubItemId);
                }
            }
        }

        /* my private folders (copy targets) */
        var mine = new GlideRecord(FOLDER_TABLE);
        mine.addQuery('owner', userId);
        mine.addQuery('is_deleted', false);
        mine.orderBy('folder_name');
        mine.query();
        while (mine.next()) {
            if (!isRecordPublic(mine)) addFolderToList(mine, data.myFolders, 'Owner');
        }

        loadRecycleBin();
        fillAttachmentIds(data.files);
        data.loaded = true;
    }

    function loadRecycleBin() {
        var folders = new GlideRecord(FOLDER_TABLE);
        folders.addQuery('owner', userId);
        folders.addQuery('is_deleted', true);
        folders.orderByDesc('sys_updated_on');
        folders.query();
        while (folders.next()) {
            if (!isRecordPublic(folders)) continue;
            data.recycleFolders.push({
                sys_id: folders.getUniqueValue(),
                folder_name: folders.getValue('folder_name') || folders.getValue('name') || '',
                color: folderColor(folders),
                created_date: folders.getDisplayValue('sys_created_on') || '',
                deleted_date: folders.getDisplayValue('deleted_date') || folders.getDisplayValue('sys_updated_on') || ''
            });
        }

        var files = new GlideRecord(FILE_TABLE);
        files.addQuery('owner', userId);
        files.addQuery('is_deleted', true);
        files.orderByDesc('sys_updated_on');
        files.query();
        while (files.next()) {
            if (!isRecordPublic(files)) continue;
            data.recycleFiles.push({
                sys_id: files.getUniqueValue(),
                filename: files.getValue('filename') || files.getValue('file_name') || files.getValue('name') || '',
                file_size: parseInt(files.getValue('file_size'), 10) || 0,
                file_extension: files.getValue('file_extension') || '',
                content_type: files.getValue('content_type') || '',
                created_date: files.getDisplayValue('sys_created_on') || '',
                deleted_date: files.getDisplayValue('deleted_date') || files.getDisplayValue('sys_updated_on') || ''
            });
        }
    }
})();
